import type { LocalizedText } from "./types";

/**
 * Kurzbeschreibungen je Kriterium, wörtlich von den anklickbaren
 * Kriterien-Kacheln auf www.qet-masterclass.com übernommen (DE/EN/TR-
 * Versionen der Seite, Stand 2026-09). Dienen dem "i"-Info-Button in der
 * Ergebnisansicht, damit Teilnehmende fachlichen Hintergrund zum jeweiligen
 * Kriterium erhalten. Hinweis: Für E05 stellt die Seite auch in der
 * türkischen Version nur den deutschen Text bereit (Lücke auf der Quelle).
 */
export const CRITERION_DESCRIPTIONS: Record<string, LocalizedText> = {
  E01: {
    de: "Jedes Unternehmen, das langfristigen Erfolg anstrebt, sollte die Werte einer Gesellschaft kennen und sich weitgehend an ihnen orientieren. Moralische und religiöse Werte sind für die Unternehmensethik relevant. Auch Tradition spielt eine wichtige Rolle. Die Werte heutiger westlicher Gesellschaften gruppieren sich unter anderem um folgende Grundbegriffe: Gerechtigkeit, Vertrauen, Verlässlichkeit, Hilfsbereitschaft, Loyalität, Freiheit, Gleichheit, Gleichberechtigung und Toleranz.",
    en: "Any company aiming for long-term success should know the values of a society and largely align itself with them. Moral and religious values are relevant to corporate ethics. Tradition also plays an important role. The values of today's Western societies revolve around the following basic concepts, among others: justice, trust, reliability, helpfulness, loyalty, freedom, equality, equal rights, and tolerance.",
    tr: "Uzun vadeli başarıyı hedefleyen her şirket, bir toplumun değerlerini bilmeli ve büyük ölçüde bunlara göre hareket etmelidir. Ahlaki ve dini değerler, iş etiği için önem taşır. Gelenek de önemli bir rol oynar. Günümüz Batı toplumlarının değerleri; adalet, güven, güvenilirlik, yardımseverlik, sadakat, özgürlük, eşitlik, fırsat eşitliği ve hoşgörü gibi temel kavramlar etrafında şekillenmektedir.",
  },
  E02: {
    de: "Eine Atmosphäre des Vertrauens ist ein deutlich produktiveres Arbeitsumfeld als eines, das von Kontrolle geprägt ist. Vertrauen stärkt das Verantwortungsbewusstsein von Mitarbeitenden und Führungskräften. Daraus entsteht eine stärkere Motivationskraft.\nZugespitzt formuliert: Kontrolle ist gut, Vertrauen ist besser. Wenn Sie Mitarbeitende haben, denen Sie vertrauen können, wird Ihr Arbeitsalltag angenehmer und produktiver.\nUm eine Atmosphäre des Vertrauens zu schaffen und dauerhaft zu erhalten, ist es wichtig, dass Verstöße gegen Regeln und Grundsätze eines Unternehmens klar definierte Strafen und Sanktionen nach sich ziehen. Auf diese Weise lässt sich einem Vertrauensbruch wirksam vorbeugen.",
    en: "An atmosphere of trust is a significantly more productive work environment than one characterized by control. Trust strengthens the sense of responsibility among employees and managers. This, in turn, leads to greater motivation.\nTo put it succinctly: control is good, trust is better. If you have employees you can trust, your daily work will be more pleasant and productive.\nTo create and maintain an atmosphere of trust, it is important that violations of a company's rules and principles entail clearly defined penalties and sanctions. This is an effective way to prevent breaches of trust.",
    tr: "Güven dolu bir atmosfer, kontrol odaklı bir çalışma ortamından çok daha üretkendir. Güven, çalışanların ve yöneticilerin sorumluluk bilincini güçlendirir. Bu da daha yüksek bir motivasyon kaynağı oluşturur.\nKısaca ifade etmek gerekirse: Kontrol iyidir, güven daha iyidir. Güvenebileceğiniz çalışanlara sahip olduğunuzda, günlük iş hayatınız daha keyifli ve üretken hale gelir.\nGüven dolu bir atmosfer yaratmak ve bunu kalıcı kılmak için, şirket kurallarının ve ilkelerinin ihlal edilmesinin net bir şekilde tanımlanmış ceza ve yaptırımları beraberinde getirmesi önemlidir. Bu sayede güvenin sarsılması etkili bir şekilde önlenebilir.",
  },
  E03: {
    de: "Die Ziele des Diversity Managements sind:\n• ein positives Gesamtklima bzw. Arbeitsklima zu schaffen\n• soziale Diskriminierung von Minderheiten zu verhindern\n• Chancengleichheit für Angehörige aller Gruppen sicherzustellen\nSeit Ende der 1990er-Jahre hat sich Diversity Management zunehmend zu einem Qualitätsmerkmal moderner Unternehmenskonzepte entwickelt. Die meisten öffentlichen Ausschreibungen, etwa im Rahmen des Europäischen Sozialfonds, verlangen heute von Bewerbern, Diversität im Unternehmen zu fördern. Alle großen europäischen und amerikanischen Unternehmen und Konzerne befassen sich seit Langem mit diesem Thema, da sie andernfalls wirklich große öffentliche Aufträge nicht gewinnen könnten.",
    en: "The goals of Diversity Management are:\n• to create a positive overall or working atmosphere\n• to prevent social discrimination against minorities\n• to ensure equal opportunities for members of all groups\nSince the late 1990s, Diversity Management has increasingly become a quality characteristic of modern corporate concepts. Most public tenders today, for example within the framework of the European Social Fund, require applicants to promote diversity within the company. All large European and American companies and corporations have been dealing with this issue for a long time, as otherwise they would not be able to win truly large public contracts.",
    tr: "Çeşitlilik Yönetimi'nin hedefleri şunlardır:\n• olumlu bir genel iklim veya çalışma ortamı yaratmak\n• azınlıklara yönelik sosyal ayrımcılığı önlemek\n• tüm grupların üyeleri için fırsat eşitliğini sağlamak\n1990'ların sonundan bu yana Çeşitlilik Yönetimi, modern kurumsal konseptlerin giderek artan bir kalite göstergesi haline gelmiştir. Günümüzde, örneğin Avrupa Sosyal Fonu kapsamındaki çoğu kamu ihalesi, başvuru sahiplerinden şirket bünyesinde çeşitliliği teşvik etmelerini talep etmektedir. Tüm büyük Avrupalı ve Amerikalı şirketler ve holdingler, aksi takdirde çok büyük kamu ihalelerini kazanamayacakları için uzun süredir bu konuyla ilgilenmektedir.",
  },
  E04: {
    de: "Das Thema Beschäftigungssicherheit ist ein schmaler Grat. Man muss das richtige Maß finden zwischen einer hektischen „hire and fire“-Mentalität und der sogenannten „Rente für den Nichtrentner“, also der „Jobgarantie mit Wellness-Faktor“, wie es oft plakativ in der Presse heißt. \nAngestellte sollten also einerseits keine übertriebene Angst vor einer Kündigung haben müssen, sich aber andererseits auch nicht zu sicher fühlen. Beide Extreme vermindern Leistung und Motivation. In diesem Zusammenhang ist von Seiten der Unternehmensleitung viel Fingerspitzengefühl gefragt. Den Vorrang sollte aber auf jeden Fall die Beschäftigungssicherheit haben.",
    en: "The topic of job security is a fine line. The right balance must be struck between a hectic \"hire and fire\" mentality and the so-called \"pension for those who don't retire,\" meaning the \"job guarantee with a wellness factor,\" as it's often sensationally reported in the press.\nEmployees should not have to live in excessive fear of being fired, but on the other hand, they should not feel too secure either. Both extremes reduce performance and motivation. In this context, a great deal of tact is required from management. However, job security should definitely take precedence.",
    tr: "İstihdam güvenliği konusu ince bir çizgidir. Hızlı bir \"işe al ve çıkar\" zihniyeti ile basında sıkça abartılı bir şekilde ifade edilen, \"emekli olmayanlar için emeklilik\" yani \"sağlık faktörlü iş garantisi\" arasında doğru dengeyi bulmak gerekir.\n\nDolayısıyla çalışanlar bir yandan işten çıkarılma korkusunu aşırı derecede yaşamamalı, diğer yandan da kendilerini fazla güvende hissetmemelidir. Her iki uç nokta da performansı ve motivasyonu düşürür. Bu bağlamda şirket yönetiminin büyük bir hassasiyet göstermesi gerekir. Ancak her halükarda öncelik istihdam güvenliğinde olmalıdır.",
  },
  E05: {
    de: "Datenschutz schützt personenbezogene Daten vor Missbrauch. Im europäischen Rechtsraum wird der Begriff „Datenschutz“ auch gesetzlich verwendet. Personenbezogene Daten einer Person dürfen nur gespeichert und verarbeitet werden, wenn dem kein Gesetz entgegensteht oder die betroffene Person bewusst eingewilligt hat.\nNutzen:\n• Sie erfüllen damit gesetzliche Anforderungen.\n• Sie stärken das Vertrauen von Mitarbeitenden, Geschäftspartnern und Kunden in Ihr Unternehmen.\n• Datenschutzmaßnahmen schaffen Synergieeffekte im Bereich Informationsschutz und Datensicherheit.",
    en: "Data protection safeguards personal data against misuse. In the European legal system, the term \"data protection\" is also used in a statutory context. Personal data of an individual may only be stored and processed if no law prohibits it or if the data subject has consciously consented.\nBenefits:\n• You thus fulfill legal requirements.\n• You strengthen the trust of employees, business partners, and customers in your company.\n• Data protection measures create synergy effects in the areas of information protection and data security.",
    tr: "Datenschutz schützt personenbezogene Daten vor Missbrauch. Im europäischen Rechtsraum wird der Begriff „Datenschutz“ auch gesetzlich verwendet. Personenbezogene Daten einer Person dürfen nur gespeichert und verarbeitet werden, wenn dem kein Gesetz entgegensteht oder die betroffene Person bewusst eingewilligt hat.\nNutzen:\n• Sie erfüllen damit gesetzliche Anforderungen.\n• Sie stärken das Vertrauen von Mitarbeitenden, Geschäftspartnern und Kunden in Ihr Unternehmen.\n• Datenschutzmaßnahmen schaffen Synergieeffekte im Bereich Informationsschutz und Datensicherheit.",
  },
  E06: {
    de: "Könnte Ihr Unternehmen Gesundheits- und Sicherheitsvorschriften noch besser überwachen? Beginnen Sie im Kleinen: Würden Sie den ganzen Tag auf dem Bürostuhl Ihrer Assistenz sitzen wollen, oder bekämen Sie Rückenschmerzen? Würden Sie mit den Empfangsmitarbeitenden tauschen wollen, die jeden Arbeitstag acht Stunden im zugigen Foyer sitzen? Fallen Ihnen Möglichkeiten ein, Ihr Unternehmen zu verbessern?\nEin gesundes Arbeitsumfeld trägt wesentlich zur Zufriedenheit der Mitarbeitenden bei. Das Arbeitsumfeld spielt hierbei eine Schlüsselrolle. Und zufriedene Mitarbeitende sind ein hervorragender Werbeträger für jedes Unternehmen.",
    en: "Could your company monitor health and safety regulations even more effectively? Start small: Would you want to sit in your assistant's office chair all day, or would you get a backache? Would you want to swap places with the reception staff who sit in the draughty foyer for eight hours every working day? Can you think of ways to improve your company?\nA healthy work environment contributes significantly to employee satisfaction. The work environment plays a key role here. And satisfied employees are an excellent advertisement for any company.",
    tr: "Şirketiniz sağlık ve güvenlik yönetmeliklerini daha iyi denetleyebilir mi? İşe küçük adımlarla başlayın: Asistanınızın ofis koltuğunda tüm gün oturmak ister miydiniz, yoksa sırtınız mı ağrırdı? Her iş günü sekiz saat boyunca hava akımına maruz kalan bir lobide oturan resepsiyon görevlileriyle yer değiştirmek ister miydiniz? Şirketinizi iyileştirmek için aklınıza gelen yollar var mı?\nSağlıklı bir çalışma ortamı, çalışan memnuniyetine önemli ölçüde katkıda bulunur. Çalışma ortamı bu noktada kilit bir rol oynar. Memnun çalışanlar ise her şirket için mükemmel birer marka elçisidir.",
  },
  E07: {
    de: "Vorübergehender Termindruck oder eine besondere Leistungsbereitschaft im Zustand hoher Konzentration („Flow“) können positiven Stress erzeugen. Dieser Stress hat in der Regel keine gesundheitsschädlichen Auswirkungen und ist daher positiv zu bewerten. Wenn positiver Stress und damit jede berufliche Herausforderung fehlen, kann der gegenteilige Effekt eintreten: das sogenannte Bore-out-Syndrom. „Bore“ bedeutet Langeweile.\nNegativer Arbeitsstress ist problematisch: Er tritt seltener bei Führungskräften auf und deutlich häufiger in mittleren und nachgeordneten Positionen. Negativer Stress entsteht oft durch körperlich belastende, gering qualifizierte Tätigkeiten mit eingeschränktem Handlungsspielraum. Die Folgen dieses negativen Stresses sind hohe Arbeitsunfähigkeitsraten und krankheitsbedingte Ausfälle.\nNegativer Stress am Arbeitsplatz geht mit innerer Anspannung und Unruhe einher, bis hin zu starkem Unwohlsein, Angst und Bedrohungsgefühlen. Stress entsteht häufig dann, wenn Belastungen extrem sind und Anforderungen die eigenen Fähigkeiten übersteigen.",
    en: "Temporary time pressure or a special willingness to perform in a state of high concentration (\"flow\") can generate positive stress. This stress generally has no detrimental effects on health and is therefore to be regarded positively. If positive stress and thus every professional challenge is absent, the opposite effect can occur: the so-called bore-out syndrome. \"Bore\" means boredom.\nNegative work-related stress is problematic: It occurs less frequently among executives and significantly more often in middle and subordinate positions. Negative stress often arises from physically demanding, low-skilled jobs with limited scope for action. The consequences of this negative stress are high rates of incapacity to work and illness-related absences.\nNegative stress at work is accompanied by inner tension and restlessness, even leading to severe discomfort, anxiety, and feelings of threat. Stress often arises when demands are extreme and exceed one's own abilities.",
    tr: "Geçici zaman baskısı veya yüksek konsantrasyon durumunda (\"akış\" hali) ortaya çıkan özel bir çalışma isteği, olumlu stres yaratabilir. Bu stresin genellikle sağlığa zararlı etkileri yoktur ve bu nedenle olumlu olarak değerlendirilir. Olumlu stresin ve dolayısıyla her türlü mesleki zorluğun eksikliği, tam tersi bir etkiye, yani \"bore-out\" (bıkkınlık) sendromuna yol açabilir. \"Bore\", can sıkıntısı anlamına gelir.\nOlumsuz iş stresi sorunludur: Yöneticilerde daha az, orta ve alt kademe pozisyonlarda ise çok daha sık görülür. Olumsuz stres genellikle fiziksel olarak zorlayıcı, düşük nitelikli ve hareket alanı kısıtlı işlerden kaynaklanır. Bu olumsuz stresin sonuçları, yüksek iş göremezlik oranları ve hastalık kaynaklı devamsızlıklardır.\nİş yerindeki olumsuz stres; içsel gerginlik ve huzursuzlukla birlikte ortaya çıkar, hatta şiddetli rahatsızlık, kaygı ve tehdit duygularına kadar varabilir. Stres, genellikle yükler aşırı olduğunda ve talepler kişinin kendi yeteneklerini aştığında ortaya çıkar.",
  },
  E08: {
    de: "Faire Arbeitsbedingungen fördern Arbeitsleistung, Identifikation mit dem Unternehmen und Loyalität gegenüber dem Unternehmen. Zu diesen fairen Arbeitsbedingungen gehört selbstverständlich auch die Vergütung. Die Einhaltung nationaler Tarifregelungen und innerbetrieblicher Vereinbarungen, etwa zu Leistungsprämien, Beförderungen oder Bonusregelungen, wird erwartet. Dies ist positiv für diejenigen, deren Arbeitsplatz für die Zukunft gesichert ist.\nMit zunehmender Digitalisierung unserer Wirtschaft und dem damit verbundenen Beschäftigungsrückgang in ganzen Branchen werden verschiedene soziale Umverteilungsmodelle intensiv diskutiert. Der Drogeriemarktgründer Götz Werner setzte sich beispielsweise für ein bedingungsloses Grundeinkommen für alle Bürgerinnen und Bürger ein. Unternehmen und Gesellschaft müssten hier grundlegend umdenken. Sie sollten sich mit diesen Zukunftsfragen befassen, um ein Gespür dafür zu entwickeln, worum es geht.",
    en: "Fair working conditions promote performance, identification with the company, and loyalty to the company. Fair working conditions naturally include remuneration. Compliance with national collective bargaining agreements and internal company agreements, such as those concerning performance bonuses, promotions, or bonus schemes, is expected. This is positive for those whose jobs are secure for the future.\nWith the increasing digitalization of our economy and the associated decline in employment in entire sectors, various social redistribution models are being intensively discussed. For example, drugstore founder Götz Werner advocated for an unconditional basic income for all citizens. Companies and society would have to fundamentally rethink their approach here. They should address these future issues to develop a sense of what is at stake.",
    tr: "Adil çalışma koşulları; iş performansını, şirketle özdeşleşmeyi ve şirkete olan bağlılığı destekler. Adil çalışma koşullarının doğal bir parçası da elbette ücretlendirmedir. Ulusal toplu iş sözleşmesi düzenlemelerine ve performans primleri, terfiler veya bonus düzenlemeleri gibi şirket içi anlaşmalara uyulması beklenmektedir. Bu durum, iş yeri geleceği güvence altında olanlar için olumludur.\nEkonomimizin giderek dijitalleşmesi ve buna bağlı olarak tüm sektörlerde yaşanan istihdam kaybı ile birlikte, çeşitli sosyal yeniden dağıtım modelleri yoğun bir şekilde tartışılmaktadır. Örneğin, drugstore zinciri kurucusu Götz Werner, tüm vatandaşlar için koşulsuz temel gelir uygulamasını savunmuştur. Şirketler ve toplum bu konuda köklü bir zihniyet değişikliğine gitmelidir. Konunun ne olduğunu anlamak ve bir fikir edinmek adına bu gelecek sorularıyla ilgilenmelidirler.",
  },
  E09: {
    de: "Die heute üblichen Arbeitszeitmodelle sind:\n• feste Arbeitszeiten\n• gleitende Arbeitszeiten\n• Schichtarbeit\n• Bandbreitenmodell\nNutzen:\n• Flexible Arbeitszeitmodelle können eingesetzt werden, um Auftragsschwankungen auszugleichen und Spitzen abzudecken, ohne zusätzliches Personal einzustellen.\n• Familie und Beruf lassen sich besser vereinbaren; die Zufriedenheit der Mitarbeitenden steigt.\n• Sie sparen wertvolle Zeit.\n• Sie fördern Eigenverantwortung und Effizienz.",
    en: "The common working time models today are:\n• fixed working hours\n• flextime\n• shift work\n• bandwidth model\nBenefits:\n• Flexible working time models can be used to compensate for order fluctuations and cover peak loads without hiring additional staff.\n• Family and career can be better reconciled; employee satisfaction increases.\n• You save valuable time.\n• They promote personal responsibility and efficiency.",
    tr: "Günümüzde yaygın olan çalışma saati modelleri şunlardır:\n• sabit çalışma saatleri\n• esnek çalışma saatleri (kayan çalışma saatleri)\n• vardiyalı çalışma\n• bant genişliği modeli\nFaydaları:\n• Esnek çalışma modelleri, ek personel alımı yapmaksızın sipariş dalgalanmalarını dengelemek ve yoğun dönemleri karşılamak için kullanılabilir.\n• Aile ve iş hayatı daha iyi dengelenebilir; çalışan memnuniyeti artar.\n• Değerli zamanınızdan tasarruf edersiniz.\n• Sorumluluk bilincini ve verimliliği teşvik eder.",
  },
  E10: {
    de: "Vor dem Hintergrund rückläufiger Geburtenraten bis zur Jahrtausendwende ist Familienfreundlichkeit einer der zentralen Wettbewerbsfaktoren für unsere Gesellschaft und insbesondere für kleine und mittlere Unternehmen. Die gegenläufige Entwicklung bestätigt, dass sich die Entscheidung für Kinder zunehmend besser mit den Realitäten der Arbeitswelt vereinbaren lässt. Ein Ausgleich zwischen familiären Verpflichtungen und beruflichen Anforderungen, also Work-Life-Balance, ist daher notwendig.\nFamilienfreundliche Maßnahmen zahlen sich für Unternehmen aus, weil\n• die Mehrheit der Mitarbeitenden ein erfolgreiches Berufsleben mit einem erfüllten Familienleben verbinden möchte.\n• die Wirtschaft auf das Wissen von Männern und Frauen angewiesen ist.\n• zufriedene Eltern besser arbeiten, motivierter, produktiver und konzentrierter sind.\n• Mütter und Väter in der Familie wichtige Kompetenzen erwerben, auch für ihre berufliche Laufbahn.\n• qualifizierte Fachkräfte gewonnen und gebunden werden können.\n• das Unternehmen Kostenvorteile erzielt (weniger Einarbeitungszeiten und Wechselkosten) und innovativer wird.\n• familienfreundliche Unternehmen als attraktive und verantwortungsvolle Arbeitgeber wahrgenommen werden (Employer Branding).\n• mehr Kinder Wachstum, Wohlstand und die beste Investition in die Zukunft bedeuten.",
    en: "Against the backdrop of declining birth rates until the turn of the millennium, family-friendliness is one of the central competitive factors for our society and especially for small and medium-sized enterprises. The opposing trend confirms that the decision to have children can increasingly be reconciled with the realities of the working world. A balance between family obligations and professional demands, i.e., work-life balance, is therefore necessary.\nFamily-friendly measures pay off for companies because\n• the majority of employees want to combine a successful professional life with a fulfilling family life.\n• the economy relies on the knowledge of men and women.\n• satisfied parents work better; they are more motivated, productive, and focused.\n• mothers and fathers acquire important skills in the family, also for their professional careers.\n• qualified specialists can be attracted and retained.\n• the company achieves cost advantages (less training time and turnover costs) and becomes more innovative.\n• family-friendly companies are perceived as attractive and responsible employers (employer branding).\n• more children mean growth, prosperity, and the best investment in the future.",
    tr: "Binyılın başına kadar süregelen doğum oranlarındaki düşüş göz önüne alındığında, aile dostu olmak toplumumuz ve özellikle küçük ve orta ölçekli işletmeler için temel rekabet faktörlerinden biridir. Tam tersi yöndeki gelişmeler, çocuk sahibi olma kararının iş dünyasının gerçekleriyle giderek daha iyi bir şekilde bağdaştırılabildiğini doğrulamaktadır. Bu nedenle, ailevi sorumluluklar ile mesleki gereklilikler arasında bir denge, yani iş-yaşam dengesi kurulması zorunludur.\n\nAile dostu önlemler şirketler için kazançlıdır çünkü:\n• Çalışanların büyük çoğunluğu başarılı bir iş hayatını tatmin edici bir aile yaşamıyla birleştirmek istemektedir.\n• Ekonomi, kadınların ve erkeklerin bilgisine ihtiyaç duymaktadır.\n• Memnun ebeveynler daha iyi çalışır, daha motive, daha üretken ve daha odaklanmış olurlar.\n• Anneler ve babalar aile içinde, mesleki kariyerleri için de geçerli olan önemli yetkinlikler kazanırlar.\n• Nitelikli uzmanlar kazanılabilir ve kuruma bağlılıkları sağlanabilir.\n• Şirket maliyet avantajları elde eder (daha az işe alıştırma süresi ve personel değişim maliyeti) ve daha yenilikçi hale gelir.\n• Aile dostu şirketler, çekici ve sorumlu işverenler olarak algılanır (İşveren Markası).\n• Daha fazla çocuk; büyüme, refah ve geleceğe yapılan en iyi yatırım anlamına gelir.",
  },
  E11: {
    de: "Im wirtschaftlichen Kontext bedeutet Beteiligung Mitarbeiterbeteiligung. Gemeint ist damit eine Beziehung zwischen Arbeitgebern und Mitarbeitenden, die über das traditionelle Arbeitsverhältnis hinausgeht und partnerschaftliche Elemente enthält.\nMitarbeiterbeteiligung kann als Kapital- oder Erfolgsbeteiligung gestaltet werden sowie als Beteiligung der Mitarbeitenden an der Gestaltung von Arbeitsprozessen und Arbeitsbedingungen. Auch die gesetzlich vorgesehenen Mitbestimmungsmöglichkeiten in Mitarbeitervertretungen (MAV, Betriebsrat, Personalrat) ermöglichen Mitarbeitenden die Beteiligung an betrieblichen Entscheidungen.",
    en: "In an economic context, participation means employee participation. This refers to a relationship between employers and employees that goes beyond the traditional employment relationship and includes elements of partnership.\nEmployee participation can take the form of capital or profit sharing, or as employee involvement in the design of work processes and working conditions. The legally stipulated co-determination rights in employee representative bodies (MAV, works council, staff council) also enable employees to participate in operational decisions.",
    tr: "Ekonomik bağlamda katılım, çalışan katılımı anlamına gelir. Bu, işverenler ile çalışanlar arasında geleneksel iş ilişkisinin ötesine geçen ve ortaklık unsurları barındıran bir ilişkiyi ifade eder.\nÇalışan katılımı; sermaye veya kâr paylaşımı şeklinde olabileceği gibi, çalışanların iş süreçlerinin ve çalışma koşullarının tasarlanmasına dahil edilmesi şeklinde de kurgulanabilir. Ayrıca, çalışan temsilciliklerinde (çalışan temsilciliği, iş yeri sendika temsilciliği, personel temsilciliği) yasal olarak öngörülen ortak karar alma imkanları da çalışanların işletme kararlarına katılımını sağlar.",
  },
  E12: {
    de: "Auch kleine und mittlere Unternehmen (KMU) richten ihren Blick zunehmend auf das wachsende Angebot gut ausgebildeter Frauen am Arbeitsmarkt.\nEin höherer Frauenanteil im Unternehmen kann sehr vorteilhaft sein: Es gibt zahlreiche positive Berichte über den Erfolg gemischter Teams. Aufgrund des Fachkräftemangels werden deutsche Unternehmen künftig noch stärker auf die Arbeitskraft hochqualifizierter Frauen angewiesen sein. Dies gilt selbst auf der obersten Führungsebene.\nDie französische Philosophin Simone de Beauvoir (1908–1986) wurde mit ihrem Buch „Das andere Geschlecht“ (1949) zu einer weltbekannten Frauenrechtlerin. Darin findet sich sinngemäß folgender Satz: Da ich nicht der Ansicht bin, dass die Frau dem Mann von Natur aus unterlegen ist, bin ich auch nicht der Ansicht, dass sie ihm von Natur aus überlegen ist.",
    en: "Small and medium-sized enterprises (SMEs) are increasingly focusing on the growing supply of well-qualified women in the labor market.\nA higher proportion of women in a company can be very advantageous: There are numerous positive reports about the success of mixed teams. Due to the shortage of skilled workers, German companies will become even more dependent on the labor of highly qualified women in the future. This also applies at the highest management level.\nThe French philosopher Simone de Beauvoir (1908–1986) became a world-renowned feminist with her book \"The Second Sex\" (1949). It contains the following sentence, in essence: As I do not believe that women are naturally inferior to men, I also do not believe that they are naturally superior to them.",
    tr: "Küçük ve orta ölçekli işletmeler (KOBİ'ler) de giderek artan bir şekilde iş gücü piyasasındaki iyi eğitimli kadınların sunduğu olanaklara yönelmektedir.\nŞirketlerde kadın oranının daha yüksek olması oldukça avantajlı olabilir: Karma ekiplerin başarısına dair çok sayıda olumlu rapor bulunmaktadır. Nitelikli iş gücü açığı nedeniyle Alman şirketleri, gelecekte yüksek nitelikli kadınların iş gücüne daha da fazla ihtiyaç duyacaktır. Bu durum, en üst yönetim kademeleri için bile geçerlidir.\nFransız filozof Simone de Beauvoir (1908–1986), 1949 tarihli \"İkinci Cins\" adlı kitabıyla dünyaca ünlü bir kadın hakları savunucusu haline gelmiştir. Kitapta mealen şu cümle yer almaktadır: Kadının doğası gereği erkeğe aşağı olduğuna inanmadığım gibi, doğası gereği ondan üstün olduğuna da inanmıyorum.",
  },
  E13: {
    de: "Der Begriff „50Plus“ bzw. „Age Management“ hat gute Chancen, zu einem zentralen neuen Schlüsselbegriff für Personalverantwortliche zu werden. Er bezeichnet ältere Mitarbeitende, also Beschäftigte ab 50 Jahren.\nFrüher wurden sie häufig mit allen Mitteln aus dem Arbeitsleben gedrängt. Dies hat sich angesichts der demografischen Entwicklung grundlegend verändert, da ältere Arbeitskräfte zunehmend unverzichtbar werden.\nIn diesem Zusammenhang ist wichtig, sich bewusst zu machen, dass ältere Menschen viele Stärken haben. Sie sind erfahrener, gelassener und häufig belastbarer sowie verlässlicher als junge Menschen. Ziel eines fortschrittlichen Unternehmens sollte es daher sein, seine Mitarbeitenden bis zum Renteneintritt zu beschäftigen.",
    en: "The terms \"50Plus\" and \"Age Management\" have a good chance of becoming central new key concepts for HR managers. They refer to older employees, i.e., those aged 50 and above.\nPreviously, they were often forced out of the workforce by all means. This has fundamentally changed given demographic developments, as older workers are becoming increasingly indispensable.\nIn this context, it is important to realize that older people have many strengths. They are more experienced, calmer, and often more resilient and reliable than younger people. The goal of a progressive company should therefore be to employ its staff until retirement.",
    tr: "\"50Plus\" veya \"Yaş Yönetimi\" (Age Management) kavramı, İnsan Kaynakları yöneticileri için merkezi bir yeni anahtar kelime olma potansiyeline sahiptir. Bu kavram, yaşlı çalışanları, yani 50 yaş ve üzerindeki çalışanları ifade eder.\nEskiden bu çalışanlar her yolla iş hayatından uzaklaştırılırdı. Demografik gelişmeler göz önüne alındığında, yaşlı iş gücünün giderek vazgeçilmez hale gelmesiyle bu durum kökten değişmiştir.\nBu bağlamda, yaşlı insanların birçok güçlü yönü olduğunun bilincinde olmak önemlidir. Onlar, gençlere kıyasla daha deneyimli, daha sakin ve genellikle daha dayanıklı ve güvenilirdirler. Bu nedenle, ilerici bir şirketin hedefi, çalışanlarını emeklilik yaşına kadar istihdam etmek olmalıdır.",
  },
  E14: {
    de: "Bei Inklusion geht es um Gleichberechtigung und Gleichbehandlung aller Menschen, unabhängig davon, woher sie kommen, wie alt sie sind, welcher Religion sie angehören oder ob sie keiner Religion angehören usw. In diesem Kapitel richten wir den Fokus auf Menschen mit Behinderungen im wirtschaftlichen Kontext der Inklusion.\nStellen Sie sich vor, Sie hätten eine Behinderung. Wie möchten Sie behandelt werden? Mit ständiger Überwachung, übertriebener Fürsorge oder einfach normal, höflich und respektvoll?\nUm dies zu erreichen, müssen im Unternehmen die richtigen Rahmenbedingungen geschaffen werden. Wir müssen unsere Denkweisen verändern. Die Inklusionsdebatte ist in vollem Gange. Seien Sie Vorreiter!",
    en: "Inclusion is about the equality and equal treatment of all people, regardless of where they come from, how old they are, what religion they belong to or if they belong to no religion, etc. In this chapter, we focus on people with disabilities in the economic context of inclusion.\nImagine you had a disability. How would you want to be treated? With constant monitoring, excessive care, or simply normally, politely, and respectfully?\nTo achieve this, the right conditions must be created within the company. We need to change our mindsets. The inclusion debate is in full swing. Be a pioneer!",
    tr: "Kapsayıcılık; nereden geldiklerine, yaşlarına, hangi dine mensup olduklarına veya herhangi bir dine mensup olup olmadıklarına bakılmaksızın tüm insanların eşit haklara ve eşit muameleye sahip olmasıyla ilgilidir. Bu bölümde, kapsayıcılığın ekonomik bağlamında engelli bireylere odaklanıyoruz.\nBir engeliniz olduğunu hayal edin. Nasıl muamele görmek isterdiniz? Sürekli bir gözetimle mi, aşırı bir ilgiyle mi, yoksa sadece normal, nazik ve saygılı bir şekilde mi?\nBunu başarmak için şirket içinde doğru çerçeve koşullarının oluşturulması gerekir. Düşünce yapımızı değiştirmeliyiz. Kapsayıcılık tartışması tüm hızıyla devam ediyor. Öncü olun!",
  },
  E15: {
    de: "Die Zahl älterer Mitarbeitender wird in den kommenden Jahren steigen. Infolge des demografischen Wandels wird es immer weniger jüngere Mitarbeitende geben. Dadurch wird auch das Durchschnittsalter der Belegschaft steigen. Unternehmen laufen daher Gefahr, mit steigenden Krankenständen konfrontiert zu werden.\nHier setzt das Betriebliche Eingliederungsmanagement (BEM) an. Ziel ist unter anderem, die Arbeitsfähigkeit von Mitarbeitenden wiederherzustellen und zu erhalten, die innerhalb von zwölf Monaten länger als sechs Wochen krankheitsbedingt ausgefallen sind. Deutsche Unternehmen sind seit 2004 gesetzlich verpflichtet, BEM-Maßnahmen anzubieten. Viele Unternehmen haben bereits positive Erfahrungen mit BEM, also der Betreuung gesundheitlich beeinträchtigter Mitarbeitender, gemacht und dadurch Krankenstände deutlich reduziert.",
    en: "The number of older employees will increase in the coming years. As a result of demographic change, there will be fewer and fewer younger employees. This will also lead to an increase in the average age of the workforce. Companies therefore run the risk of facing rising sickness rates.\nThis is where company integration management (BEM) comes in. One of its goals is to restore and maintain the employability of employees who have been absent due to illness for more than six weeks within twelve months. German companies have been legally obliged to offer BEM measures since 2004. Many companies have already had positive experiences with BEM, i.e., the support of employees with health impairments, and have significantly reduced sickness rates as a result.",
    tr: "Yaşlı çalışanların sayısı önümüzdeki yıllarda artacak. Demografik değişim nedeniyle genç çalışanların sayısı giderek azalacak. Bu durum, iş gücünün yaş ortalamasının da yükselmesine neden olacak. Şirketler bu nedenle artan hastalık izinleri ile karşı karşıya kalma riskiyle karşı karşıyadır.\n\nİşyeri Entegrasyon Yönetimi (BEM) tam da bu noktada devreye giriyor. Hedeflerden biri, on iki ay içinde altı haftadan uzun süre hastalık nedeniyle işe gelemeyen çalışanların çalışma kapasitelerini yeniden kazandırmak ve korumaktır. Alman şirketleri, 2004 yılından bu yana yasal olarak BEM önlemleri sunmakla yükümlüdür. Birçok şirket, BEM yani sağlık sorunları yaşayan çalışanların desteklenmesi konusunda halihazırda olumlu deneyimler edinmiş ve bu sayede hastalık izinlerini önemli ölçüde azaltmıştır.",
  },
  E16: {
    de: "Ein Ziel betrieblicher Aus- und Weiterbildung besteht darin, die beruflichen Fähigkeiten einer Mitarbeiterin bzw. eines Mitarbeiters aufzubauen, zu erhalten oder zu erweitern, um die berufliche Entwicklung dieser Person zu fördern.\nIn einigen Berufsfeldern ist Weiterbildung Voraussetzung für die rechtmäßige Berufsausübung. Im Bildungsbereich oder in medizinisch-therapeutischen Tätigkeiten ist die Berufsausübungserlaubnis beispielsweise an die regelmäßige Teilnahme an Fortbildungsveranstaltungen gebunden. In anderen Berufen benötigen Mitarbeitende Weiterbildung, um sich künftig gegenüber Wettbewerbern behaupten zu können.",
    en: "One goal of corporate training and professional development is to build, maintain, or expand an employee's professional skills to foster their career development.\nIn some professional fields, continuing education is a prerequisite for the lawful practice of the profession. In education or medical-therapeutic professions, for example, the license to practice is tied to regular participation in professional development courses. In other professions, employees need continuing education to be able to compete with rivals in the future.",
    tr: "Kurumsal eğitim ve gelişimin bir amacı, çalışanın mesleki gelişimini desteklemek için mesleki becerilerini oluşturmak, korumak veya genişletmektir.\nBazı meslek alanlarında mesleki gelişim, mesleğin yasal olarak icra edilebilmesi için bir ön koşuldur. Örneğin eğitim sektöründe veya tıbbi-terapötik faaliyetlerde, mesleği icra etme izni düzenli olarak mesleki gelişim etkinliklerine katılıma bağlıdır. Diğer mesleklerde ise çalışanlar, gelecekte rakiplerine karşı ayakta kalabilmek için mesleki gelişime ihtiyaç duyarlar.",
  },
  E17: {
    de: "Der Begriff „Compliance“ bedeutet im Deutschen sinngemäß die Einhaltung von Gesetzen und Regeln. Compliance beschreibt die Gesamtheit aller angemessenen und sinnvollen Maßnahmen, die das regel- und grundsatzkonforme Verhalten eines Unternehmens und seiner Mitarbeitenden im Hinblick auf alle gesetzlichen Gebote und Verbote sicherstellen.\nDarüber hinaus muss auch das Geschäftsverhalten des Unternehmens mit allen gesellschaftlichen Leitlinien und Werten, also mit geltender Moral und Ethik, im Einklang stehen.\nIm Wirtschaftsgebrauch bezeichnet Compliance die Einhaltung von Gesetzen und spezifischen Richtlinien, aber auch die dauerhafte Befolgung freiwillig geschaffener Unternehmenskodizes. Im Deutschen kann dieser schwer zu übersetzende Begriff daher auch Regelüberwachung oder schlicht Überwachung bedeuten. Compliance gilt heute als wichtiges Element ordnungsgemäßer Corporate Governance.",
    en: "In German, the term \"Compliance\" generally means adherence to laws and rules. Compliance describes the entirety of all appropriate and sensible measures that ensure a company and its employees act in accordance with rules and principles, with regard to all legal commands and prohibitions.\nFurthermore, the company's business conduct must also align with all societal guidelines and values, meaning with applicable morals and ethics.\nIn business terms, compliance refers to adherence to laws and specific guidelines, as well as the continuous observance of voluntarily established company codes. In German, this difficult-to-translate term can therefore also mean regulatory monitoring or simply monitoring. Compliance is now considered an important element of proper corporate governance.",
    tr: "Almancada \"Compliance\" terimi, yasalara ve kurallara uyum anlamına gelir. Compliance, bir şirketin ve çalışanlarının tüm yasal emir ve yasaklar doğrultusunda kural ve ilkelere uygun davranış sergilemesini sağlayan tüm makul ve anlamlı önlemlerin bütününü tanımlar.\nBunun ötesinde, şirketin ticari davranışlarının tüm toplumsal kılavuz ilkeler ve değerlerle, yani yürürlükteki ahlak ve etik kurallarıyla da uyumlu olması gerekir.\nİş dünyasında Compliance, yasaların ve belirli yönergelerin yanı sıra gönüllü olarak oluşturulan şirket kodlarına sürekli uyumu ifade eder. Almancada çevrilmesi zor olan bu terim, bu nedenle kural denetimi veya kısaca denetim anlamına da gelebilir. Compliance günümüzde, düzgün bir kurumsal yönetimin önemli bir unsuru olarak kabul edilmektedir.",
  },
  E18: {
    de: "Die Fair-Trade-Bewegung konzentrierte sich bisher vor allem auf Waren, die aus ärmeren Ländern in wohlhabendere Länder exportiert werden. Heute umfasst Fair Trade landwirtschaftliche Produkte ebenso wie traditionelles Kunsthandwerk und Industrieprodukte und weitet sich zunehmend auf Dienstleistungen im Tourismus- und IT-Sektor aus. Fair-Trade-Produkte wurden zunächst in Bio- und Weltläden verkauft, sind heute jedoch auch in Supermärkten und Restaurants erhältlich.\nViele Organisationen sind heute unter dem Dach der „Fairtrade Labelling Organizations International“ (FLO) zusammengeschlossen, die 1997 in Bonn gegründet wurde. Da es besser klingt, wird diese Organisation heute meist „Fairtrade International“ genannt. Sie vergibt das Fairtrade-Siegel nach ihrem eigenen FLO-Standard.",
    en: "The Fair Trade movement has so far focused primarily on goods exported from poorer to wealthier countries. Today, Fair Trade includes agricultural products as well as traditional handicrafts and industrial products, and is increasingly expanding into services in the tourism and IT sectors. Fair Trade products were initially sold in organic and world shops, but are now also available in supermarkets and restaurants.\nMany organizations are now united under the umbrella of \"Fairtrade Labelling Organizations International\" (FLO), which was founded in Bonn in 1997. As it sounds better, this organization is now usually called \"Fairtrade International\". It awards the Fairtrade label according to its own FLO standard.",
    tr: "Adil Ticaret hareketi, bugüne kadar ağırlıklı olarak daha yoksul ülkelerden daha varlıklı ülkelere ihraç edilen mallara odaklanmıştır. Günümüzde Adil Ticaret, tarım ürünlerinin yanı sıra geleneksel el sanatlarını ve endüstriyel ürünleri de kapsamakta; turizm ve bilişim sektörlerindeki hizmetlere doğru giderek genişlemektedir. Başlangıçta sadece organik ürün mağazalarında ve dünya dükkanlarında satılan Adil Ticaret ürünleri, günümüzde süpermarketlerde ve restoranlarda da bulunabilmektedir.\nBirçok kuruluş bugün, 1997 yılında Bonn'da kurulan \"Fairtrade Labelling Organizations International\" (FLO) çatısı altında birleşmiştir. Kulağa daha hoş geldiği için bu kuruluş günümüzde genellikle \"Fairtrade International\" olarak adlandırılmaktadır. Kuruluş, kendi FLO standartlarına göre Fairtrade sertifikası vermektedir.",
  },
  E19: {
    de: "Umweltmanagement befasst sich unter anderem mit der Sicherstellung der nachhaltigen Umweltverträglichkeit von Unternehmensprozessen und Produkten, Umweltpolitik und technischen Maßnahmen, der Entsorgung umweltgefährdender Stoffe und Altgeräte, der Einhaltung behördlicher Anforderungen und Grenzwerte sowie der Standardisierungsverantwortung gegenüber den sogenannten Stakeholdern. Stakeholder sind die Betroffenen, in diesem Zusammenhang also Personen und Gruppen, die ein berechtigtes Interesse daran haben, dass ein Unternehmen ökologische Anforderungen einhält.",
    en: "Environmental management deals, among other things, with ensuring the sustainable environmental compatibility of corporate processes and products, environmental policy and technical measures, the disposal of environmentally hazardous substances and old equipment, compliance with official requirements and limits, and the responsibility for standardization towards so-called stakeholders. Stakeholders are those affected, in this context meaning individuals and groups who have a legitimate interest in a company complying with ecological requirements.",
    tr: "Çevre yönetimi; kurumsal süreçlerin ve ürünlerin sürdürülebilir çevresel uyumluluğunun sağlanması, çevre politikası ve teknik önlemler, çevreye zararlı maddelerin ve eski cihazların bertarafı, resmi gerekliliklere ve sınır değerlere uyumun yanı sıra paydaşlara karşı standardizasyon sorumluluğu gibi konularla ilgilenir. Paydaşlar, bu bağlamda bir şirketin ekolojik gerekliliklere uymasında meşru bir çıkarı olan ilgili kişi ve gruplardır.",
  },
  E20: {
    de: "„Corporate Social Responsibility“ lässt sich ungefähr mit „gesellschaftliche Verantwortung eines Unternehmens“ übersetzen. CSR ist heute in den meisten großen Unternehmen und internationalen Konzernen fester Bestandteil der Unternehmenskultur. Insbesondere Familienunternehmen erfüllen ihre gesellschaftliche Verantwortung seit Generationen in besonders werteorientierter Weise.\nGesellschaftliche Verantwortung beginnt im Unternehmen selbst – bei der Unternehmensleitung, den Mitarbeitenden und dem Umweltbewusstsein –, reicht dann über die Verbraucherinnen und Verbraucher hinaus und mündet in konkretem und sinnvollem Engagement für das Gemeinwesen. Ein Unternehmen, das sich CSR verpflichtet fühlt, trägt auch soziale Verantwortung gegenüber Produzenten und Lieferanten sowie entlang der gesamten Lieferkette. CSR spielt im globalen Handeln von Unternehmen eine zunehmend wichtige Rolle. So bewertet die deutsche Verbraucherschutzorganisation „Stiftung Warentest“ seit 2004 bei vielen Produkten die „Übernahme von Verantwortung entlang der gesamten Wertschöpfungskette im Hinblick auf soziale und ökologische Aspekte“ und prüft Produktions- und Fertigungsstätten im Ausland.",
    en: "\"Corporate Social Responsibility\" roughly translates to \"the social responsibility of a company.\" Today, CSR is an integral part of the corporate culture in most large companies and international corporations. Family businesses, in particular, have been fulfilling their social responsibility in a particularly value-oriented manner for generations.\nSocial responsibility begins within the company itself – with management, employees, and environmental awareness – then extends beyond consumers and culminates in concrete and meaningful commitment to the community. A company that feels committed to CSR also bears social responsibility towards producers and suppliers, as well as along the entire supply chain. CSR plays an increasingly important role in the global operations of companies. For example, since 2004, the German consumer protection organization \"Stiftung Warentest\" has been evaluating \"the assumption of responsibility along the entire value chain with regard to social and ecological aspects\" for many products and inspecting production and manufacturing sites abroad.",
    tr: "\"Kurumsal Sosyal Sorumluluk\" (CSR), kabaca \"bir şirketin toplumsal sorumluluğu\" olarak çevrilebilir. CSR, günümüzde çoğu büyük şirketin ve uluslararası kuruluşun kurum kültürünün ayrılmaz bir parçasıdır. Özellikle aile şirketleri, toplumsal sorumluluklarını nesillerdir son derece değer odaklı bir şekilde yerine getirmektedir.\nToplumsal sorumluluk, şirket içinde; şirket yönetimi, çalışanlar ve çevre bilinci ile başlar, ardından tüketicilerin ötesine uzanır ve toplum için somut ve anlamlı bir katkıya dönüşür. CSR'ye bağlılık duyan bir şirket, üreticilere ve tedarikçilere karşı olduğu kadar, tüm tedarik zinciri boyunca da sosyal sorumluluk taşır. CSR, şirketlerin küresel faaliyetlerinde giderek daha önemli bir rol oynamaktadır. Örneğin, Alman tüketici koruma kuruluşu \"Stiftung Warentest\", 2004 yılından bu yana birçok üründe \"sosyal ve çevresel açılardan tüm değer zinciri boyunca sorumluluk üstlenilmesini\" değerlendirmekte ve yurt dışındaki üretim ve imalat tesislerini denetlemektedir.",
  },
  Q01: {
    de: "Führungskompetenzen und die Beherrschung von Managementmethoden sind nicht dasselbe. Von einem Manager wird erwartet, dass er über methodische Kompetenzen verfügt. Er sollte in der Lage sein zu planen, zu führen, zu delegieren, zu moderieren und Entscheidungen zu treffen. Fachliche Kompetenzen wie Branchenkenntnisse, Kenntnis von Standards und Vertrautheit mit gängigen Qualitätsmanagementsystemen (QM) sollten hierfür die Grundlage bilden. Beherrscht der Manager diese, ist es in spezifischen Arbeitsbereichen ausreichend. Eine Führungspersönlichkeit verfügt über Kompetenzen, die darüber hinausgehen.",
    en: "Leadership skills and mastery of management methods are not the same. A manager is expected to have methodological competence. They should be able to plan, guide, delegate, moderate, and make decisions. Technical skills such as industry knowledge, familiarity with standards, and common quality management systems (QM) should form the basis for this. If the manager masters these, it is sufficient in specific work areas. A leader possesses skills that go beyond this.",
    tr: "Liderlik becerileri ile yönetim yöntemlerine hakimiyet aynı şey değildir. Bir yöneticiden yöntemsel yetkinliklere sahip olması beklenir. Planlama, yönetme, yetki devretme, moderasyon yapma ve karar alma becerilerine sahip olmalıdır. Sektörel bilgi, standartlara hakimiyet ve yaygın kalite yönetim sistemlerine (QM) aşinalık gibi mesleki yetkinlikler bunun temelini oluşturmalıdır. Yönetici bunlara hakimse, belirli çalışma alanlarında bu yeterlidir. Bir lider ise bunun ötesine geçen yetkinliklere sahiptir.",
  },
  Q02: {
    de: "Eine herausragende Führungskraft zeichnet sich nicht nur im Bereich des Handelns und des nachhaltigen geschäftlichen Erfolgs durch besondere Merkmale aus, sondern auch im sozialen Bereich – also im Umgang mit anderen Menschen. \n\nDabei handelt es sich um Eigenschaften und Fähigkeiten, die heute unter dem Begriff „Soft Skills“ zusammengefasst werden. Es geht um Wertschätzung, Respekt, Vertrauen und Toleranz, aber auch um kulturelle Kompetenz – das heißt die Fähigkeit, sich in andere Kulturen und Lebenswelten hineinzuversetzen. Eine gute Führungskraft besitzt die Fähigkeit zur Teamarbeit sowie zum konstruktiven Umgang mit Konflikten und Kritik; sie kommuniziert souverän, ist flexibel und leistungsbereit.",
    en: "An outstanding leader is distinguished not only in their actions and sustainable business success but also in the social sphere – meaning in their interactions with others.\n\nThese are qualities and abilities now summarized under the term \"soft skills.\" They include appreciation, respect, trust, and tolerance, but also cultural competence – that is, the ability to empathize with other cultures and ways of life. A good leader possesses the ability to work in a team and to deal constructively with conflicts and criticism; they communicate confidently, are flexible, and are committed to performance.",
    tr: "Üstün bir yönetici, sadece eylem ve sürdürülebilir ticari başarı alanındaki özel nitelikleriyle değil, aynı zamanda sosyal alanda, yani diğer insanlarla olan ilişkilerinde de öne çıkar.\n\nBu durum, günümüzde \"sosyal beceriler\" (soft skills) terimi altında toplanan özellik ve yetenekleri ifade eder. Burada söz konusu olan; değer verme, saygı, güven ve hoşgörünün yanı sıra kültürel yetkinliktir; yani başka kültürleri ve yaşam dünyalarını anlama ve empati kurabilme becerisidir. İyi bir yönetici, ekip çalışmasına yatkınlık ile çatışma ve eleştirileri yapıcı bir şekilde yönetme yeteneğine sahiptir; özgüvenli bir şekilde iletişim kurar, esnektir ve yüksek performans göstermeye isteklidir.",
  },
  Q03: {
    de: "Management und Leadership unterscheiden sich im Wesentlichen wie folgt:\n\n• Management bedeutet, im Organisationssystem zu arbeiten.\n• Leadership bedeutet, am Organisationssystem zu arbeiten.\n\nIn Zeiten der Globalisierung und sich wandelnder Märkte werden Führungspersönlichkeiten benötigt, die Menschen aus allen Hierarchieebenen zusammenführen und auf eine neue Ausrichtung orientieren können. Leadership kann erlernt werden.\n\nDaher sollten Unternehmen, die künftig nachhaltigen Erfolg erreichen möchten, ihre Talente zielgerichtet und mit langfristiger Perspektive identifizieren, fördern und entwickeln.",
    en: "Management and leadership essentially differ as follows:\n\n• Management means working within the organizational system.\n• Leadership means working on the organizational system.\n\nIn times of globalization and changing markets, leaders are needed who can bring together people from all hierarchical levels and orient them towards a new direction. Leadership can be learned.\n\nTherefore, companies that want to achieve sustainable success in the future should identify, promote, and develop their talents in a targeted manner and with a long-term perspective.",
    tr: "Yönetim ve liderlik arasındaki temel farklar şöyledir:\n\n• Yönetim, organizasyon sistemi içinde çalışmak anlamına gelir.\n• Liderlik, organizasyon sistemi üzerinde çalışmak anlamına gelir.\n\nKüreselleşme ve değişen pazar koşullarının yaşandığı günümüzde, her hiyerarşik kademeden insanı bir araya getirebilecek ve onları yeni bir doğrultuda yönlendirebilecek liderlik vasıflarına sahip kişilere ihtiyaç duyulmaktadır. Liderlik öğrenilebilir bir beceridir.\n\nBu nedenle, gelecekte sürdürülebilir başarı elde etmek isteyen şirketler, yeteneklerini hedef odaklı bir şekilde ve uzun vadeli bir perspektifle belirlemeli, desteklemeli ve geliştirmelidir.",
  },
  Q04: {
    de: "Veränderungen in Organisation, Technologie, Betriebsstrukturen und Arbeitsinhalten stellen kontinuierlich neue Anforderungen an die Qualifikationen der Mitarbeitenden.\nDer amerikanische Ökonom österreichischer Herkunft Peter Ferdinand Drucker (1909–2005) gilt als Wegbereiter der modernen Managementlehre. Viele erfolgreiche Unternehmen orientieren sich bis heute an seinem bekannten Grundsatz:\nEine gute Führungskraft achtet stärker darauf, was ein Mitarbeitender kann,\nals auf das, was er nicht kann.",
    en: "Changes in organization, technology, operational structures, and job content continuously place new demands on employees' qualifications.\nThe American economist of Austrian origin Peter Ferdinand Drucker (1909–2005) is considered a pioneer of modern management theory. Many successful companies still follow his well-known principle today:\nA good leader focuses more on what an employee can do\nthan on what they cannot do.",
    tr: "Organizasyondaki, teknolojideki, operasyonel yapılardaki ve iş içeriklerindeki değişimler, çalışanların yetkinliklerine sürekli olarak yeni talepler getirmektedir.\nAvusturya asıllı Amerikalı ekonomist Peter Ferdinand Drucker (1909–2005), modern yönetim biliminin öncüsü olarak kabul edilir. Birçok başarılı şirket, günümüzde hâlâ onun şu bilinen ilkesini temel almaktadır:\nİyi bir yönetici, bir çalışanın yapamadıklarından ziyade, yapabildiklerine daha fazla odaklanır.",
  },
  Q05: {
    de: "Eigenverantwortung, also Engagement und Antrieb, wird im Unternehmen gefördert, wenn Führungskräfte auf die folgenden Grundbedürfnisse der Mitarbeiter achten:\nSoziale Bedürfnisse: Menschen mögen das Gefühl, zu einer Gruppe zu gehören, und wollen als Team zusammenarbeiten. Führungskräfte sollten daher den Zusammenhalt und den Teamgeist innerhalb der Belegschaft fördern. Zahlreiche Studien haben gezeigt, dass die Bedeutung des Arbeitsklimas in vielen Unternehmen oft unterschätzt wird.\nWertschätzung durch Erfolg, Status und Anerkennung: Die meisten Menschen suchen Anerkennung von Freunden, Kollegen und Vorgesetzten. Sie erhalten die gewünschte Anerkennung in Form von finanziellen Belohnungen, beruflicher Weiterentwicklung und einem gestärkten Selbstbewusstsein durch Bestätigung.",
    en: "Personal responsibility, i.e. commitment and drive, is promoted in a company when managers pay attention to the following basic needs of employees:\nSocial needs: People like the feeling of belonging to a group and want to work together as a team. Managers should therefore promote cohesion and team spirit within the workforce. Numerous studies have shown that the importance of the working atmosphere is often underestimated in many companies.\nAppreciation through success, status and recognition: Most people seek recognition from friends, colleagues and superiors. They receive the desired recognition in the form of financial rewards, professional development and strengthened self-confidence through affirmation.",
    tr: "Şirket içinde öz sorumluluk, yani bağlılık ve motivasyon, yöneticiler çalışanların aşağıdaki temel ihtiyaçlarına dikkat ettiklerinde desteklenmiş olur:\nSosyal ihtiyaçlar: İnsanlar bir gruba ait olma duygusundan hoşlanır ve bir ekip olarak birlikte çalışmak isterler. Bu nedenle yöneticiler, çalışanlar arasındaki dayanışmayı ve ekip ruhunu teşvik etmelidir. Çok sayıda araştırma, çalışma ortamının öneminin birçok şirkette genellikle hafife alındığını göstermiştir.\nBaşarı, statü ve takdir yoluyla değer görme: İnsanların çoğu arkadaşları, meslektaşları ve yöneticilerinden takdir bekler. İstedikleri takdiri finansal ödüller, mesleki gelişim ve onaylanma yoluyla güçlenen bir özgüven şeklinde alırlar.",
  },
  Q06: {
    de: "Change Management ist die systematische Planung, Steuerung und Kontrolle von Veränderungen in Unternehmen. Es umfasst die koordiniert gesteuerte und kontrollierte Initiierung, Planung, Durchführung und abschließende Bewertung von technischen oder betrieblichen Änderungen. Während des Change-Management-Prozesses muss besonders darauf geachtet werden, dass Stabilität, Kontinuität und Qualität der angebotenen Dienste bei systemrelevanten Änderungen nicht beeinträchtigt werden. Neben formalen Aspekten der Planung berücksichtigt gutes Change Management zunehmend auch „weiche“ Faktoren der Veränderung wie etwa die Verbesserung interner Kommunikation, den Umgang mit Widerständen oder die Steigerung der Motivation.",
    en: "Change Management is the systematic planning, steering, and control of changes within companies. It encompasses the coordinated, managed, and controlled initiation, planning, execution, and final evaluation of technical or operational changes. During the change management process, particular attention must be paid to ensuring that the stability, continuity, and quality of the services offered are not impaired by system-relevant changes. In addition to formal aspects of planning, good change management increasingly also considers \"soft\" factors of change, such as improving internal communication, dealing with resistance, or increasing motivation.",
    tr: "Değişim Yönetimi, şirketlerdeki değişimlerin sistematik olarak planlanması, yönlendirilmesi ve kontrol edilmesidir. Teknik veya operasyonel değişikliklerin koordineli bir şekilde başlatılmasını, planlanmasını, uygulanmasını ve nihai değerlendirmesini kapsar. Değişim yönetimi süreci sırasında, sistem açısından kritik değişikliklerde sunulan hizmetlerin istikrarının, sürekliliğinin ve kalitesinin olumsuz etkilenmemesine özellikle dikkat edilmelidir. İyi bir değişim yönetimi, planlamanın biçimsel yönlerinin yanı sıra, iç iletişimin iyileştirilmesi, dirençle başa çıkma veya motivasyonun artırılması gibi değişimin \"yumuşak\" faktörlerini de giderek daha fazla dikkate almaktadır.",
  },
  Q07: {
    de: "Die Aufgabenbereiche des Human Resources Managements (HRM) sind vielfältig. Dazu gehören Personalplanung und Bedarfsanalyse, Recruiting, Personalentwicklung, Management-Trainee-Programme, Personaleinsatzplanung, Personalführung, Mitarbeitendenbetreuung sowie Vergütungssysteme.\nDieser Bereich ist von zentraler Bedeutung, da der Erfolg eines Unternehmens maßgeblich vom optimalen Einsatz seiner personellen Ressourcen abhängt. Engagement, Wissen und Kompetenzen qualifizierter Mitarbeitender bilden die Grundlage eines leistungsfähigen Unternehmens.\nUm exzellentes Personalmanagement sicherzustellen, können Unternehmen eigene qualifizierte Auswahlverfahren wie Assessment Center einsetzen oder erfahrene externe Personalberatungen beauftragen. Eine kosteneffiziente Alternative besteht darin, geeignete Mitarbeitende intern durch gezielte Weiterbildungsmaßnahmen für diese verantwortungsvollen Aufgaben zu qualifizieren.",
    en: "The responsibilities of Human Resources Management (HRM) are diverse. These include HR planning and needs analysis, recruiting, personnel development, management trainee programs, workforce scheduling, personnel management, employee support, and compensation systems.\nThis area is of central importance, as a company's success largely depends on the optimal deployment of its human resources. The commitment, knowledge, and skills of qualified employees form the foundation of a high-performing company.\nTo ensure excellent personnel management, companies can use their own qualified selection processes such as assessment centers or engage experienced external HR consultancies. A cost-effective alternative is to qualify suitable employees internally for these responsible tasks through targeted training measures.",
    tr: "İnsan Kaynakları Yönetimi'nin (İKY) görev alanları oldukça çeşitlidir. Bunlar arasında personel planlaması ve ihtiyaç analizi, işe alım, personel geliştirme, yönetici adayı programları, personel görevlendirme planlaması, personel yönetimi, çalışan desteği ve ücretlendirme sistemleri yer almaktadır.\nBu alan, bir şirketin başarısı büyük ölçüde insan kaynaklarının en verimli şekilde kullanılmasına bağlı olduğundan merkezi bir öneme sahiptir. Nitelikli çalışanların bağlılığı, bilgisi ve yetkinlikleri, başarılı bir şirketin temelini oluşturur.\nMükemmel bir personel yönetimini sağlamak için şirketler, değerlendirme merkezleri (Assessment Center) gibi kendi nitelikli seçim süreçlerini uygulayabilir veya deneyimli dış personel danışmanlık firmalarından hizmet alabilirler. Uygun maliyetli bir alternatif ise, mevcut çalışanları hedef odaklı eğitim programlarıyla bu sorumluluk gerektiren görevler için şirket içinde yetiştirmektir.",
  },
  Q08: {
    de: "Das Produktmanagement trägt bereichsübergreifende Verantwortung für ein Produkt oder eine Produktlinie. Produkt- und Markenmanagement bilden dabei eine eigenständige Managementebene.\nGrundsätzlich ist die Produktmanagerin bzw. der Produktmanager für den wirtschaftlichen Erfolg eines Produkts oder einer Produktgruppe verantwortlich. Zu den wichtigsten Aufgabenfeldern des Produktmanagements gehören:\nDie Erkenntnis über die Bedeutung professionellen Produktmanagements verhalf dem bedeutenden US-Unternehmer Henry Ford (1863–1947) zu nachhaltigem Erfolg:\nNicht der Unternehmer bezahlt die Löhne – er reicht lediglich das Geld weiter. Das Produkt bezahlt die Löhne.",
    en: "Product management carries cross-functional responsibility for a product or product line. Product and brand management form an independent management level.\nEssentially, the product manager is responsible for the economic success of a product or product group. The most important tasks of product management include:\nThe realization of the importance of professional product management helped the significant US entrepreneur Henry Ford (1863–1947) achieve lasting success:\nThe employer doesn't pay the wages – they merely hand over the money. The product pays the wages.",
    tr: "Ürün yönetimi, bir ürün veya ürün grubu için bölümler arası sorumluluk taşır. Ürün ve marka yönetimi bu noktada bağımsız bir yönetim kademesi oluşturur.\nTemel olarak ürün yöneticisi, bir ürünün veya ürün grubunun ticari başarısından sorumludur. Ürün yönetiminin en önemli görev alanları şunlardır:\nProfesyonel ürün yönetiminin öneminin kavranması, önemli ABD'li girişimci Henry Ford'un (1863–1947) kalıcı bir başarı elde etmesini sağlamıştır:\nMaaşları ödeyen girişimci değildir; o sadece parayı iletir. Maaşları ödeyen üründür.",
  },
  Q09: {
    de: "Studien zeigen, dass nur etwa jede siebte Produktidee zu einem Markterfolg führt. Dafür gibt es viele Gründe, häufig tritt jedoch folgendes Problem im Hinblick auf Kundinnen und Kunden auf:\nWer sich zu stark auf eigene technische Ideen konzentriert, kann am Markt scheitern. Oft besteht ein Kommunikationsdefizit zwischen Produktentwicklung und Kundschaft. Die Regel ist einfach: Der Wurm muss dem Fisch schmecken – nicht dem Angler.",
    en: "Studies show that only about one in seven product ideas leads to market success. There are many reasons for this, but the following problem often arises with regard to customers:\nThose who focus too much on their own technical ideas can fail in the market. Often there is a communication deficit between product development and customers. The rule is simple: The worm must taste good to the fish – not the angler.",
    tr: "Araştırmalar, her yedi ürün fikrinden sadece birinin ticari başarıya ulaştığını gösteriyor. Bunun birçok nedeni olsa da, müşteriler özelinde genellikle şu sorunla karşılaşılmaktadır:\nKendi teknik fikirlerine gereğinden fazla odaklananlar, pazarda başarısız olabilirler. Ürün geliştirme ekibi ile müşteri kitlesi arasında genellikle bir iletişim kopukluğu yaşanır. Kural basittir: Yem, balıkçının değil, balığın hoşuna gitmelidir.",
  },
  Q10: {
    de: "Das Arbeiten in Netzwerken und Netzwerkorganisationen entspricht den neuen, offenen Formen von Unternehmensführung. Durch Vernetzung kann sich ein Unternehmen nicht nur gegenüber dem Wettbewerb abgrenzen und positionieren, sondern vornehmlich auch mit anderen Marktteilnehmern in Kooperation gehen. Wichtig ist dabei, dass das Unternehmen als Organisation mit wechselnden Partnern einen offenen Kommunikationsstil pflegt. \nDarüber hinaus erlaubt Vernetzung das flexible Ausweiten und Reduzieren von Kapazitäten und Kompetenzen je nach Bedarf und damit eine elegantere Anpassung an Arbeitsbedingungen im rasanten Wandel.",
    en: "Working in networks and network organizations aligns with new, open forms of corporate management. Through networking, a company can not only differentiate and position itself against the competition but, above all, enter into cooperation with other market participants. It is important that the company, as an organization with changing partners, maintains an open communication style.\nFurthermore, networking allows for the flexible expansion and reduction of capacities and competencies as needed, thus enabling a more elegant adaptation to rapidly changing working conditions.",
    tr: "Ağlar ve ağ organizasyonları içinde çalışmak, yeni ve açık kurumsal yönetim biçimlerine karşılık gelir. Ağ oluşturma sayesinde bir şirket, sadece rekabet karşısında kendini farklılaştırıp konumlandırmakla kalmaz, aynı zamanda diğer pazar katılımcılarıyla iş birliğine de gidebilir. Bu noktada önemli olan, şirketin bir organizasyon olarak değişken ortaklarla açık bir iletişim tarzı sürdürmesidir.\nBunun ötesinde ağ oluşturma, kapasite ve yetkinliklerin ihtiyaca göre esnek bir şekilde artırılıp azaltılmasına ve dolayısıyla hızla değişen çalışma koşullarına daha zarif bir şekilde uyum sağlanmasına olanak tanır.",
  },
  Q11: {
    de: "Ist Ihre Unternehmensphilosophie mit den angebotenen Produkten und Dienstleistungen vereinbar? Haben Sie Ihre Zielgruppe klar im Blick? Beobachten Sie Markt, Wettbewerb und die kontinuierlichen Veränderungen der Kundenbedürfnisse? Dann befinden Sie sich auf dem richtigen Weg zum Aufbau einer starken Marke, die Ihrem Unternehmen einen entscheidenden Wettbewerbsvorteil verschaffen kann.\nWenn Unternehmen sich im Wettbewerb um Fach- und Führungskräfte als attraktive Arbeitgeber positionieren möchten, nutzen sie sogenanntes Employer Branding als strategische Marketingmaßnahme.",
    en: "Is your corporate philosophy compatible with the products and services you offer? Do you have a clear understanding of your target audience? Do you monitor the market, competition, and continuous changes in customer needs? Then you are on the right path to building a strong brand that can give your company a decisive competitive advantage.\nIf companies want to position themselves as attractive employers in the competition for skilled workers and executives, they use so-called employer branding as a strategic marketing measure.",
    tr: "Şirket felsefeniz, sunduğunuz ürün ve hizmetlerle uyumlu mu? Hedef kitlenizi net bir şekilde belirlediniz mi? Pazarı, rekabeti ve müşteri ihtiyaçlarındaki sürekli değişimleri takip ediyor musunuz? O halde, şirketinize belirleyici bir rekabet avantajı sağlayabilecek güçlü bir marka oluşturma yolunda doğru ilerliyorsunuz demektir.\nŞirketler, nitelikli iş gücü ve yönetici adayları arasındaki rekabette kendilerini çekici bir işveren olarak konumlandırmak istediklerinde, stratejik bir pazarlama aracı olarak işveren markalaşmasını (Employer Branding) kullanırlar.",
  },
  Q12: {
    de: "Der Begriff „Qualität“ ist eine der drei Grundsäulen von QET, da er beispielhaft für die Unternehmenskultur des 21. Jahrhunderts steht.\nWir verstehen diesen Begriff daher in einem umfassenden Sinn, der sich auf die richtige Haltung der Unternehmensführung bezieht. Heute verfügt nahezu jedes Unternehmen über einen Bereich, der diesen Begriff mit Leben füllt. Im operativen Geschäft ist dafür in der Regel das Qualitätsmanagement verantwortlich.",
    en: "The term \"quality\" is one of the three foundational pillars of QET, as it exemplifies the corporate culture of the 21st century.\nWe therefore understand this term in a comprehensive sense, referring to the correct attitude of corporate leadership. Today, almost every company has a department that embodies this concept. In operational business, quality management is typically responsible for this.",
    tr: "\"Kalite\" kavramı, 21. yüzyılın kurumsal kültürünü örneklediği için QET'in üç temel direğinden biridir.\nBu nedenle bu kavramı, şirket yönetiminin doğru duruşunu ifade eden kapsamlı bir anlamda ele alıyoruz. Günümüzde neredeyse her şirketin bu kavramı hayata geçiren bir departmanı bulunmaktadır. Operasyonel iş süreçlerinde ise bundan genellikle kalite yönetimi sorumludur.",
  },
  Q13: {
    de: "Allein in Bayern sind jährlich rund 12.000 mittelständische Unternehmen mit etwa 100.000 Arbeitsplätzen betroffen. In 70 Prozent der Fälle wird eine Unternehmensnachfolge aufgrund des Ruhestands der Unternehmensinhaberin bzw. des Unternehmensinhabers erforderlich. Die übrigen 30 Prozent entstehen durch wirtschaftliches Scheitern, berufliche Neuorientierung des Managements oder akute Notfälle wie Unfälle, Krankheit oder den Tod der Unternehmensleitung. In 44 Prozent der Familienunternehmen ist die Existenz des Unternehmens durch eine krisenbedingte Nachfolgesituation gefährdet.\nNutzen:\n• Der Fortbestand des Unternehmens wird gesichert.\n• Die neue Führungspersönlichkeit setzt neue Impulse für das Unternehmen.\n• Der Führungswechsel bringt zugleich einen Generationenwechsel mit sich.",
    en: "In Bavaria alone, around 12,000 medium-sized businesses employing approximately 100,000 people are affected annually. In 70 percent of cases, a business succession becomes necessary due to the retirement of the owner. The remaining 30 percent arise from economic failure, professional reorientation of management, or acute emergencies such as accidents, illness, or the death of the company's leadership. In 44 percent of family businesses, the company's existence is threatened by a crisis-related succession situation.\nBenefits:\n• The continued existence of the company is secured.\n• The new leader brings new impetus to the company.\n• The change in leadership also brings about a generational change.",
    tr: "Sadece Bavyera'da her yıl yaklaşık 12.000 orta ölçekli işletme ve bu işletmelerde çalışan yaklaşık 100.000 kişi bu durumdan etkilenmektedir. Vakaların yüzde 70'inde şirket devri, şirket sahibinin emekliliği nedeniyle gerekli hale gelmektedir. Geriye kalan yüzde 30'luk kısım ise ekonomik başarısızlıklar, yönetimin kariyer değişikliği veya kaza, hastalık ya da şirket yönetiminin vefatı gibi acil durumlardan kaynaklanmaktadır. Aile şirketlerinin yüzde 44'ünde, kriz kaynaklı bir devir süreci şirketin varlığını tehdit etmektedir.\nFaydaları:\n• Şirketin devamlılığı güvence altına alınır.\n• Yeni liderlik profili, şirkete yeni bir ivme kazandırır.\n• Liderlik değişimi, aynı zamanda bir kuşak değişimini de beraberinde getirir.",
  },
  Q14: {
    de: "Ressourcenmanagement umfasst heute längst nicht mehr nur quantitative und technische Aspekte. Auch Herkunft und Umweltverträglichkeit der eingesetzten Ressourcen gewinnen zunehmend an Bedeutung. Ressourcenschonung wird heute ebenfalls ausdrücklich erwartet. Dadurch wird die Aufgabe des Ressourcenmanagements vielseitiger und verantwortungsvoller.\nKundinnen und Kunden sind heute aufmerksamer und selbstbewusster. Sie hinterfragen genauer. Als Unternehmerin bzw. Unternehmer und insbesondere im Ressourcenmanagement müssen Sie sich darauf einstellen.",
    en: "Resource management today no longer encompasses only quantitative and technical aspects. The origin and environmental compatibility of the resources used are also gaining increasing importance. Resource conservation is also explicitly expected today. This makes the task of resource management more diverse and responsible.\nCustomers today are more attentive and self-aware. They question things more closely. As an entrepreneur, and especially in resource management, you must adapt to this.",
    tr: "Günümüzde kaynak yönetimi artık sadece nicel ve teknik yönlerden ibaret değildir. Kullanılan kaynakların menşei ve çevresel etkileri de giderek daha fazla önem kazanmaktadır. Kaynak tasarrufu artık açıkça beklenen bir standart haline gelmiştir. Bu durum, kaynak yönetimini çok daha yönlü ve sorumluluk gerektiren bir görev haline getirmektedir.\nMüşteriler günümüzde çok daha dikkatli ve bilinçlidir. Her şeyi daha detaylı sorgulamaktadırlar. Bir girişimci olarak ve özellikle kaynak yönetimi alanında buna hazırlıklı olmanız gerekmektedir.",
  },
  Q15: {
    de: "Effiziente Prozessoptimierung ermöglicht Unternehmen, Geschäfts-, Produktentwicklungs- und Konstruktionsprozesse sowie den Ressourceneinsatz kontinuierlich zu verbessern. Heute erfolgt dies überwiegend mithilfe digitaler Softwarelösungen.\nProzessoptimierung galt lange Zeit als Aufgabe des Qualitätsmanagements. Heute ist sie eine zentrale Säule des integrierten Prozessmanagements in Unternehmen und Institutionen. Prozessorientiertes Denken und Prozessoptimierung als Grundlage effektiver Unternehmenssteuerung sind für modernes Management unverzichtbar geworden, um im regionalen, nationalen und internationalen Wettbewerb bestehen zu können.",
    en: "Efficient process optimization enables companies to continuously improve business, product development, and design processes, as well as resource utilization. Today, this is primarily achieved through digital software solutions.\nProcess optimization was long considered a task for quality management. Today, it is a central pillar of integrated process management in companies and institutions. Process-oriented thinking and process optimization as the foundation of effective corporate management have become indispensable for modern management to compete regionally, nationally, and internationally.",
    tr: "Verimli süreç optimasyonu, şirketlerin iş, ürün geliştirme ve tasarım süreçlerinin yanı sıra kaynak kullanımını da sürekli olarak iyileştirmelerini sağlar. Günümüzde bu süreç, ağırlıklı olarak dijital yazılım çözümleri yardımıyla gerçekleştirilmektedir.\nSüreç optimasyonu uzun bir süre kalite yönetiminin bir görevi olarak görülmüştür. Bugün ise şirketlerde ve kurumlarda entegre süreç yönetiminin temel bir direğidir. Süreç odaklı düşünme ve etkili bir şirket yönetiminin temeli olarak süreç optimasyonu, bölgesel, ulusal ve uluslararası rekabette ayakta kalabilmek adına modern yönetim için vazgeçilmez hale gelmiştir.",
  },
  Q16: {
    de: "Die konsequente Anwendung von Methoden wie Scrum als Prozessmodell für agile Softwareentwicklung sowie der entsprechenden Werkzeuge durch kompetente und motivierte Mitarbeitende entscheidet zunehmend über Erfolg oder Misserfolg. Projekte bilden dabei gewissermaßen den Mikrokosmos, in dem die Voraussetzungen moderner Unternehmensführung entwickelt werden. \n\nFür die organisatorische und operative Struktur eines Unternehmens bedeutet ein hoher Projektanteil, dass bestehende Strukturen hinterfragt, umgestaltet, aufgelöst oder teilweise ersetzt werden müssen. Die wichtigsten Herausforderungen einer flexiblen Projektorganisation sind:\n• Begrenzungen hinsichtlich Zeit und Kosten\n• Zeitfenster als Arbeitsabschnitt (Sprint)\n• Konkrete Zielsetzungen einschließlich Teilziele\n• Flexible Reaktion auf veränderte Rahmenbedingungen\n• Lösung neuer und innovativer Aufgabenstellungen\n• Verknüpfung unterschiedlicher Aufgabenbereiche\n• Teams mit Mitarbeitenden unterschiedlicher Kompetenzen",
    en: "The consistent application of methods like Scrum as a process model for agile software development, and the corresponding tools by competent and motivated employees, increasingly determines success or failure. Projects, in this sense, form the microcosm in which the prerequisites for modern corporate management are developed.\n\nFor the organizational and operational structure of a company, a high project proportion means that existing structures must be questioned, redesigned, dissolved, or partially replaced. The most important challenges of a flexible project organization are:\n• Time and cost constraints\n• Time windows as work segments (sprints)\n• Concrete objectives including sub-goals\n• Flexible response to changing conditions\n• Solving new and innovative tasks\n• Linking different task areas\n• Teams with employees of diverse competencies",
    tr: "Scrum gibi çevik yazılım geliştirme süreç modellerinin ve ilgili araçların yetkin ve motive çalışanlar tarafından tutarlı bir şekilde uygulanması, başarı veya başarısızlığı giderek daha fazla belirlemektedir. Projeler, modern kurumsal yönetimin ön koşullarının geliştirildiği bir nevi mikrokozmos oluşturur.\n\nBir şirketin organizasyonel ve operasyonel yapısı için yüksek proje oranı, mevcut yapıların sorgulanması, yeniden şekillendirilmesi, feshedilmesi veya kısmen değiştirilmesi gerektiği anlamına gelir. Esnek bir proje organizasyonunun en önemli zorlukları şunlardır:\n• Zaman ve maliyet sınırlamaları\n• Çalışma dönemi olarak zaman aralıkları (Sprint)\n• Ara hedefler dahil olmak üzere somut hedefler\n• Değişen koşullara esnek tepki verme\n• Yeni ve yenilikçi görevlerin çözümü\n• Farklı görev alanlarının birbirine bağlanması\n• Farklı yetkinliklere sahip çalışanlardan oluşan ekipler",
  },
  Q17: {
    de: "Ein modernes Unternehmen muss permanent in Bewegung bleiben. Es muss sich kontinuierlich an Markt- und Kundenanforderungen anpassen und aus Fehlern lernen – idealerweise auch aus den Fehlern der Wettbewerber. Um diesen Lernprozess strukturiert steuern zu können, bedarf es eines Wissensmanagements, das Lernprozesse dokumentiert, analysiert und daraus positive Veränderungen ableitet.\nDie digitale Revolution hat Wissen zu einer zentralen Ressource gemacht. Wissen war schon immer wichtig, heute ist seine Bedeutung jedoch so dominant geworden, dass Soziologinnen und Soziologen längst von einer Wissensgesellschaft sprechen. Eine lernende Organisation generiert zusätzliches Wissen aus eigenen Erfahrungen und verschafft sich dadurch entscheidende Wettbewerbsvorteile.",
    en: "A modern company must constantly be on the move. It must continuously adapt to market and customer requirements and learn from mistakes – ideally also from the mistakes of competitors. To be able to manage this learning process in a structured way, knowledge management is needed that documents and analyzes learning processes and derives positive changes from them.\nThe digital revolution has made knowledge a central resource. Knowledge has always been important, but today its significance has become so dominant that sociologists have long been speaking of a knowledge society. A learning organization generates additional knowledge from its own experiences and thus gains decisive competitive advantages.",
    tr: "Modern bir işletme sürekli hareket halinde kalmalıdır. Pazar ve müşteri taleplerine sürekli uyum sağlamalı ve hatalardan ders çıkarmalıdır; ideal olanı, rakiplerin hatalarından da ders almaktır. Bu öğrenme sürecini yapılandırılmış bir şekilde yönetebilmek için, öğrenme süreçlerini belgeleyen, analiz eden ve bunlardan olumlu değişimler çıkaran bir bilgi yönetimine ihtiyaç vardır.\nDijital devrim, bilgiyi merkezi bir kaynak haline getirmiştir. Bilgi her zaman önemli olmuştur, ancak günümüzde önemi o kadar baskın hale gelmiştir ki, sosyologlar uzun süredir bir bilgi toplumundan bahsetmektedir. Öğrenen bir organizasyon, kendi deneyimlerinden ek bilgi üretir ve bu sayede belirleyici rekabet avantajları elde eder.",
  },
  Q18: {
    de: "Ziel des Innovationsmanagements ist es, durch Innovationen Wettbewerbsvorteile aufzubauen und langfristig zu sichern. Dazu beobachtet es Trends, identifiziert zukunftsorientierte Technologien, bewertet deren Eignung für die jeweilige Branche, initiiert Technologietransfer und begleitet Projekte bis zur Serienreife.\nDie Globalisierung hat den Wettbewerb verschärft, und die Konkurrenz wächst kontinuierlich. Gleichzeitig gelten die Märkte in entwickelten Ländern vielfach als gesättigt. In einer solchen wirtschaftlichen Situation kann bereits eine kleine Innovation einen entscheidenden Vorteil bedeuten. Strukturiertes Innovationsmanagement gewinnt daher zunehmend an Bedeutung. Sucht Ihr Unternehmen gezielt nach Innovationen?",
    en: "The goal of innovation management is to build and secure competitive advantages through innovations in the long term. To achieve this, it monitors trends, identifies future-oriented technologies, assesses their suitability for the respective industry, initiates technology transfer, and supports projects through to series production.\nGlobalization has intensified competition, and competitors are continuously growing. At the same time, markets in developed countries are often considered saturated. In such an economic situation, even a small innovation can provide a decisive advantage. Structured innovation management is therefore becoming increasingly important. Is your company actively seeking innovations?",
    tr: "İnovasyon yönetiminin amacı, inovasyonlar yoluyla rekabet avantajı oluşturmak ve bunu uzun vadede güvence altına almaktır. Bu doğrultuda trendleri gözlemler, geleceğe yönelik teknolojileri tanımlar, bunların ilgili sektör için uygunluğunu değerlendirir, teknoloji transferini başlatır ve projeleri seri üretime hazır hale gelene kadar destekler.\nKüreselleşme rekabeti şiddetlendirmiş ve rakiplerin sayısı sürekli artmaktadır. Aynı zamanda gelişmiş ülkelerdeki pazarların büyük ölçüde doygunluğa ulaştığı kabul edilmektedir. Böyle bir ekonomik durumda, küçük bir inovasyon bile belirleyici bir avantaj sağlayabilir. Bu nedenle yapılandırılmış inovasyon yönetimi giderek daha fazla önem kazanmaktadır. Şirketiniz inovasyonları hedefli bir şekilde arıyor mu?",
  },
  Q19: {
    de: "Seit Oktober 2009 existiert ein weltweit gültiger Standard für Risikomanagement. Die Norm ISO / DIS 31000 hat das Risikomanagement zu einer Managementaufgabe aufgewertet. Theoretisch folgt dieser Standard einem Top-down-Ansatz, bei dem risikorelevante Zusammenhänge allgemein definiert und anschließend auf konkrete Einzelfälle angewendet werden.\nGeht Ihr Unternehmen offen mit Risiken um? Oder wird dieses Thema unterschätzt oder sogar ignoriert? Bedenken Sie, dass die öffentliche Wahrnehmung von Risiken in den vergangenen Jahren deutlich zugenommen hat. Medien und Nichtregierungsorganisationen (NGOs) beobachten Unternehmen heute wesentlich kritischer.",
    en: "Since October 2009, a globally valid standard for risk management has been in existence. The ISO/DIS 31000 standard has elevated risk management to a management task. Theoretically, this standard follows a top-down approach, where risk-relevant contexts are generally defined and then applied to specific individual cases.\nDoes your company deal openly with risks? Or is this topic underestimated or even ignored? Keep in mind that the public perception of risks has increased significantly in recent years. Media and non-governmental organizations (NGOs) are observing companies much more critically today.",
    tr: "Ekim 2009'dan bu yana dünya çapında geçerli bir risk yönetimi standardı bulunmaktadır. ISO / DIS 31000 standardı, risk yönetimini bir yönetim görevi seviyesine yükseltmiştir. Teorik olarak bu standart, riskle ilgili bağlantıların genel olarak tanımlandığı ve ardından somut münferit vakalara uygulandığı yukarıdan aşağıya (top-down) bir yaklaşımı izler.\nŞirketiniz risklere karşı açık bir tutum sergiliyor mu? Yoksa bu konu hafife mi alınıyor, hatta görmezden mi geliniyor? Risklerin kamuoyundaki algısının geçtiğimiz yıllarda önemli ölçüde arttığını unutmayın. Medya ve sivil toplum kuruluşları (STK'lar) günümüzde şirketleri çok daha eleştirel bir gözle takip etmektedir.",
  },
  Q20: {
    de: "Der kontinuierliche Verbesserungsprozess (KVP) ist ein häufig angewandtes Grundprinzip im Qualitätsmanagement und heute ein unverzichtbarer Bestandteil der ISO 9001. Er wurde in den 1990er-Jahren erstmals in der deutschen Automobilindustrie als deutsche Adaption des japanischen „Kaizen“ eingeführt und hat sich seitdem weit verbreitet. Kaizen wurde ursprünglich in den 1950er-Jahren vom japanischen Automobilhersteller Toyota entwickelt.\nDer Grundgedanke besteht darin, dass Mitarbeitende, die unmittelbar in den Arbeitsprozessen tätig sind, ihre Ideen aktiv in die Unternehmensführung einbringen können. Sie sollen ausdrücklich dazu ermutigt werden, Verbesserungsvorschläge einzubringen. Kaizen und kontinuierliche Verbesserung sind daher zentrale Bestandteile einer mitarbeiter- und beteiligungsorientierten Unternehmenskultur.",
    en: "The continuous improvement process (CIP) is a frequently applied fundamental principle in quality management and is now an indispensable component of ISO 9001. It was first introduced in the 1990s in the German automotive industry as a German adaptation of the Japanese \"Kaizen\" and has since become widely adopted. Kaizen was originally developed in the 1950s by the Japanese car manufacturer Toyota.\nThe underlying idea is that employees directly involved in work processes can actively contribute their ideas to company management. They should be explicitly encouraged to submit suggestions for improvement. Kaizen and continuous improvement are therefore central components of an employee and participation-oriented corporate culture.",
    tr: "Sürekli İyileştirme Süreci (KVP), kalite yönetiminde yaygın olarak uygulanan bir temel ilke olup günümüzde ISO 9001'in vazgeçilmez bir parçasıdır. 1990'lı yıllarda Japon \"Kaizen\" felsefesinin Almanca uyarlaması olarak ilk kez Alman otomotiv endüstrisinde tanıtılmış ve o günden bu yana geniş bir kullanım alanı bulmuştur. Kaizen, başlangıçta 1950'li yıllarda Japon otomobil üreticisi Toyota tarafından geliştirilmiştir.\nTemel düşünce, doğrudan iş süreçlerinin içinde yer alan çalışanların, fikirlerini şirket yönetimine aktif bir şekilde dahil edebilmeleridir. Çalışanlar, iyileştirme önerileri sunmaları konusunda açıkça teşvik edilmelidir. Bu nedenle Kaizen ve sürekli iyileştirme, çalışan ve katılım odaklı bir şirket kültürünün temel bileşenleridir.",
  },
  T01: {
    de: "Die sogenannten Leitlinien umfassen die langfristigen Ziele eines Unternehmens und dokumentieren die Werte und Strategien, auf deren Grundlage die angestrebten Unternehmensziele innerhalb eines bestimmten Zeitraums erreicht werden sollen. In diesem Sinne beschreibt das Unternehmensleitbild die Unternehmenskultur im Hinblick auf Aspekte wie Werte und Normen, strategische Ziele bzw. Visionen und Mission, Potenziale, Umgangsformen, Märkte und Umfeld.",
    en: "The so-called guidelines encompass a company's long-term goals and document the values and strategies upon which the desired corporate objectives are to be achieved within a specific timeframe. In this sense, the corporate mission statement describes the corporate culture in terms of aspects such as values and norms, strategic goals or visions and missions, potentials, conduct, markets, and environment.",
    tr: "Kurumsal ilkeler olarak adlandırılan bu rehber, bir şirketin uzun vadeli hedeflerini kapsar ve hedeflenen kurumsal amaçlara belirli bir süre zarfında ulaşılmasını sağlayacak değer ve stratejileri belgeler. Bu bağlamda kurumsal misyon bildirisi; değerler ve normlar, stratejik hedefler veya vizyon ve misyon, potansiyeller, davranış biçimleri, pazarlar ve çevre gibi açılardan şirket kültürünü tanımlar.",
  },
  T02: {
    de: "Typischerweise umfasst die CI:\nUnternehmensphilosophie, Unternehmensname, Logo, Umgangsformen, Sprach- und Begrüßungsstil, Dresscode, Unternehmenssymbole, Architektur und Gestaltung von Unternehmensgebäuden, Gestaltung von Dokumenten und Texten, visuelle und akustische Zeichen, Bürogestaltung, erkennbare Hierarchien, Sitzordnungen, Farbgestaltung, Gestaltung von Anzeigen, Terminologie und – soweit vorhanden – das besondere Leistungsversprechen des Unternehmens als Marke.",
    en: "Typically, CI includes:\nCorporate philosophy, company name, logo, manners, language and greeting style, dress code, corporate symbols, architecture and design of company buildings, design of documents and texts, visual and acoustic signs, office design, recognizable hierarchies, seating arrangements, color scheme, design of advertisements, terminology and – if applicable – the company's unique value proposition as a brand.",
    tr: "Kurumsal kimlik (CI) tipik olarak şunları kapsar:\nKurumsal felsefe, şirket adı, logo, görgü kuralları, dil ve hitap tarzı, kıyafet yönetmeliği, kurumsal semboller, şirket binalarının mimarisi ve tasarımı, belgelerin ve metinlerin tasarımı, görsel ve işitsel işaretler, ofis tasarımı, belirgin hiyerarşiler, oturma düzenleri, renk tasarımı, reklam tasarımı, terminoloji ve – mevcutsa – şirketin bir marka olarak sunduğu özel hizmet vaadi.",
  },
  T03: {
    de: "In Deutschland bestehen gesetzliche Transparenzanforderungen nur für finanzbezogene Bereiche von Unternehmen, beispielsweise in der Rechnungslegung von Kapitalgesellschaften. Der öffentliche Ruf nach Transparenz wird jedoch immer stärker. Transparenz bedeutet, interne Unternehmensstrukturen, Gegenstände und Prozesse offenzulegen. Dies kann das Vertrauen von Geschäftspartnern, Stammkunden und vor allem potenziellen Kunden stärken. Auch die Identifikation der Mitarbeitenden mit dem Unternehmen und ihre Loyalität werden gestärkt.",
    en: "In Germany, statutory transparency requirements only exist for finance-related areas of companies, such as the accounting of corporations. However, the public call for transparency is growing stronger. Transparency means disclosing internal company structures, assets, and processes. This can strengthen the trust of business partners, regular customers, and especially potential customers. It also strengthens employee identification with the company and their loyalty.",
    tr: "Almanya'da yasal şeffaflık gereklilikleri yalnızca şirketlerin finansal alanları için, örneğin sermaye şirketlerinin muhasebe süreçlerinde mevcuttur. Ancak şeffaflığa yönelik kamuoyu talebi giderek artmaktadır. Şeffaflık; şirket içi yapıların, faaliyet konularının ve süreçlerin açıklanması anlamına gelir. Bu durum iş ortaklarının, sadık müşterilerin ve özellikle potansiyel müşterilerin güvenini pekiştirebilir. Ayrıca çalışanların şirketle olan aidiyet duygusu ve bağlılıkları da güçlenir.",
  },
  T04: {
    de: "Trends im Einkaufsverhalten zeigen, dass Verbraucherinnen und Verbraucher sowie Auftraggeber zunehmend Wert auf eine „saubere“, also faire Herkunft von Produkten legen.\nAnbieter, die glaubwürdig nachweisen können, dass sie werteorientiert einkaufen und produzieren, werden künftig bessere Chancen haben. Dieser Nachweis kann auch durch eine möglichst transparente Preisgestaltung erbracht werden.\nDas gesellschaftliche Umfeld verändert sich. Werte gewinnen an Bedeutung. In den kommenden Jahren wird voraussichtlich nicht mehr „Geiz ist geil!“ gelten, sondern eher „fair ist stark!“. Unternehmen müssen sich darauf einstellen.",
    en: "Trends in purchasing behavior show that consumers and clients are increasingly valuing a \"clean,\" meaning fair, origin of products. Suppliers who can credibly demonstrate that they purchase and produce ethically will have better opportunities in the future. This proof can also be provided through the most transparent pricing possible.\nThe social environment is changing. Values are gaining importance. In the coming years, \"greed is good!\" will likely no longer apply, but rather \"fair is strong!\". Companies must adapt to this.",
    tr: "Satın alma davranışlarındaki trendler, tüketicilerin ve müşterilerin ürünlerin \"temiz\", yani adil bir kökene sahip olmasına giderek daha fazla önem verdiğini gösteriyor.\nDeğer odaklı satın alma ve üretim yaptıklarını güvenilir bir şekilde kanıtlayabilen tedarikçiler, gelecekte daha iyi fırsatlara sahip olacaklar. Bu kanıt, mümkün olduğunca şeffaf bir fiyatlandırma ile de sağlanabilir.\nToplumsal çevre değişiyor. Değerler önem kazanıyor. Önümüzdeki yıllarda muhtemelen \"ucuz olsun da nasıl olursa olsun\" anlayışı yerine \"adil olan güçlüdür\" anlayışı geçerli olacak. Şirketlerin buna uyum sağlaması gerekiyor.",
  },
  T05: {
    de: "Für eine erfolgreiche Vertragsbeziehung müssen Sie zunächst Ihre eigenen Ziele bestimmen und zugleich die Vorstellungen Ihres Vertragspartners berücksichtigen, damit eine für beide Seiten akzeptable Vereinbarung erreicht wird. Grundsätzlich wollen und sollen alle Vertragspartner vom Vertrag profitieren (Win-win-Situation).\nSobald alle wichtigen Punkte in den Vertrag aufgenommen wurden, sollten Sie – schon im Interesse des Vertragsfriedens – nicht bei allen Nebenpunkten auf hundertprozentiger Erfüllung bestehen. Vertragsfreiheit bedeutet auch, dass niemand Sie zwingen kann, ein bestimmtes Geschäft abzuschließen.",
    en: "For a successful contractual relationship, you must first define your own goals while also taking into account the expectations of your contracting partner, so that a mutually acceptable agreement can be reached. Fundamentally, all contracting parties want and should benefit from the contract (a win-win situation).\nOnce all important points have been included in the contract, you should – in the interest of contractual peace – not insist on 100% fulfillment of all minor points. Freedom of contract also means that no one can force you to conclude a particular deal.",
    tr: "Başarılı bir sözleşme ilişkisi için öncelikle kendi hedeflerinizi belirlemeli ve aynı zamanda her iki taraf için de kabul edilebilir bir anlaşmaya varılabilmesi adına sözleşme ortağınızın beklentilerini göz önünde bulundurmalısınız. Temel olarak tüm sözleşme tarafları sözleşmeden faydalanmak ister ve faydalanmalıdır (kazan-kazan durumu).\nTüm önemli noktalar sözleşmeye dahil edildikten sonra, sözleşme barışının korunması adına yan konularda yüzde yüzlük bir yerine getirme beklentisi içinde olmamalısınız. Sözleşme özgürlüğü, hiç kimsenin sizi belirli bir işi yapmaya zorlayamayacağı anlamına da gelir.",
  },
  T06: {
    de: "„Social Media“ bezeichnet soziale Netzwerke und Online-Communitys, die als virtuelle Plattformen dem gegenseitigen Austausch von Meinungen, Eindrücken und Erfahrungen dienen.\nUnabhängig davon, wie Sie zum Internet und zu sozialen Netzwerken stehen: Sie sind heute fester Bestandteil unserer Welt, und ihre Bedeutung wird voraussichtlich weiter zunehmen. Die meisten Unternehmen sind daher bereits in sozialen Netzwerken präsent. Dort befinden sich Kunden, Geschäftspartner und Mitarbeitende; dort ist ein großer Teil der Öffentlichkeit aktiv; dort kann ein gutes Image aufgebaut, aber auch schnell verloren werden, wenn ein Unternehmen negative Schlagzeilen produziert.",
    en: "\"Social media\" refers to social networks and online communities that serve as virtual platforms for the mutual exchange of opinions, impressions, and experiences.\nRegardless of your stance on the internet and social networks, they are an integral part of our world today, and their importance is expected to continue to grow. Most companies are therefore already present on social networks. That's where customers, business partners, and employees are; that's where a large part of the public is active; that's where a good image can be built, but also quickly lost if a company generates negative headlines.",
    tr: "\"Sosyal medya\", görüşlerin, izlenimlerin ve deneyimlerin karşılıklı paylaşımı için sanal platformlar görevi gören sosyal ağları ve çevrimiçi toplulukları ifade eder.\nİnternete ve sosyal ağlara bakış açınız ne olursa olsun; bunlar günümüzde dünyamızın ayrılmaz bir parçasıdır ve önemlerinin artmaya devam etmesi beklenmektedir. Bu nedenle çoğu şirket halihazırda sosyal ağlarda varlık göstermektedir. Müşteriler, iş ortakları ve çalışanlar oradadır; kamuoyunun büyük bir kısmı orada aktiftir; orada iyi bir imaj oluşturulabilir, ancak bir şirket olumsuz haberlere konu olursa bu imaj hızla kaybedilebilir.",
  },
  T07: {
    de: "„Zielvereinbarung“, „Zielformulierung“ und „Zielerreichung“ sind betriebswirtschaftliche Begriffe der Unternehmensführung, mit deren semantischer Hilfe ein Ergebnis- oder Prozessziel innerhalb einer Wertschöpfungskette und im Projektmanagement definiert wird.\nEs werden Ziele formuliert, die die Beteiligten – in der Regel innerhalb eines festgelegten Zeitraums – erreichen sollen. Zielvereinbarungen sind im sogenannten Management by Objectives (MbO) verbreitet. In diesem Verfahren, das sich als „Führung durch Zielvereinbarungen“ übersetzen lässt, werden Mitarbeitende aktiv in die Zielsetzung einbezogen und dürfen anschließend relativ frei entscheiden, wie sie die gesetzten Ziele erreichen.",
    en: "\"Goal agreement,\" \"goal formulation,\" and \"goal attainment\" are business management terms used to define a result or process goal within a value chain and in project management, with the semantic aid of these terms. Goals are formulated that the participants – typically within a defined timeframe – are expected to achieve. Goal agreements are common in what is known as Management by Objectives (MbO). In this process, which can be translated as \"management by objectives,\" employees are actively involved in setting goals and are subsequently given relatively free rein to decide how to achieve the set goals.",
    tr: "\"Hedef mutabakatı\", \"hedef belirleme\" ve \"hedefe ulaşma\", bir değer zinciri içindeki veya proje yönetimindeki bir sonuç ya da süreç hedefinin semantik yardımıyla tanımlandığı, kurumsal yönetimdeki işletme terimleridir.\nİlgili tarafların genellikle belirlenmiş bir süre içinde ulaşmaları gereken hedefler formüle edilir. Hedef mutabakatları, \"Management by Objectives\" (MbO) olarak adlandırılan yöntemde yaygındır. \"Hedeflerle yönetim\" olarak çevrilebilecek bu süreçte, çalışanlar hedef belirleme aşamasına aktif olarak dahil edilir ve ardından belirlenen hedeflere nasıl ulaşacaklarına dair nispeten özgür bir şekilde karar vermelerine izin verilir.",
  },
  T08: {
    de: "Wenn es nicht gelingt, einen Konflikt rasch zu entschärfen, kann er eskalieren und Stress sowie gesundheitliche Belastungen verursachen. Werden Konflikte konstruktiv bearbeitet, können neue Ideen gefördert und bessere Ergebnisse erzielt werden. Der Umgang mit Konflikten ist erlernbar.\nDie konsequente Anwendung bestimmter Regeln hilft, solche Probleme konstruktiv zu bewältigen. Wenn ein Konflikt nicht gelöst werden kann, kann es hilfreich sein, eine Mediatorin oder einen Mediator einzubeziehen, um unzumutbare Situationen, wie sie etwa bei Mobbing entstehen, zu verhindern oder zu beseitigen.",
    en: "If a conflict is not quickly de-escalated, it can escalate and cause stress and health problems. If conflicts are addressed constructively, new ideas can be fostered and better results achieved. Dealing with conflicts is a learnable skill.\nThe consistent application of certain rules helps to manage such problems constructively. If a conflict cannot be resolved, it may be helpful to involve a mediator to prevent or eliminate unacceptable situations, such as those that arise from bullying.",
    tr: "Bir çatışmanın hızla yatıştırılamaması durumunda, çatışma tırmanabilir ve strese yol açarak sağlık sorunlarına neden olabilir. Çatışmalar yapıcı bir şekilde ele alındığında ise yeni fikirler teşvik edilebilir ve daha iyi sonuçlar elde edilebilir. Çatışmalarla başa çıkmak öğrenilebilir bir beceridir.\nBelirli kuralların tutarlı bir şekilde uygulanması, bu tür sorunların yapıcı bir biçimde çözülmesine yardımcı olur. Bir çatışma çözülemediğinde, mobbing gibi durumlarda ortaya çıkan kabul edilemez durumları önlemek veya ortadan kaldırmak için bir arabulucudan destek almak faydalı olabilir.",
  },
  T09: {
    de: "Grundsätzlich sollte mit Fehlern konstruktiv umgegangen werden. Denn aus Fehlern kann gelernt werden. Unternehmerinnen und Unternehmer sollten sicherstellen, dass Mitarbeitende keine Sanktionen befürchten müssen, wenn Fehler – insbesondere erstmals – passieren.\nEine Fehleranalyse kann helfen, aus dem Fehler zu lernen und insgesamt davon zu profitieren, indem Prozesse verändert und optimiert werden",
    en: "Fundamentally, mistakes should be dealt with constructively, because mistakes can be learned from. Entrepreneurs should ensure that employees do not have to fear sanctions when mistakes happen – especially for the first time.\nA mistake analysis can help to learn from the mistake and ultimately benefit from it by changing and optimizing processes.",
    tr: "Hatalara karşı temel olarak yapıcı bir yaklaşım sergilenmelidir. Çünkü hatalardan ders çıkarılabilir. Girişimciler, çalışanların özellikle ilk kez yapılan hatalarda herhangi bir yaptırımdan korkmalarına gerek kalmamasını sağlamalıdır.\nBir hata analizi, hatadan ders çıkarmaya ve süreçleri değiştirip optimize ederek genel anlamda bundan fayda sağlamaya yardımcı olabilir.",
  },
  T10: {
    de: "Zu den gängigen Kriterien der Lieferantenbewertung gehören die ppm-Rate (parts per million), der Preis, Mengen- und Termintreue, Innovationsfähigkeit sowie zunehmend die Werteorientierung des Lieferanten.\nAuf die Lieferantenbewertung im Rahmen einer Nutzwertanalyse folgt eine Klassifizierung in A-, B- und C-Lieferanten. A-Lieferanten werden bevorzugt, weil sie beispielsweise in der Vergangenheit die höchste Lieferqualität erbracht haben.",
    en: "Common criteria for supplier evaluation include the ppm rate (parts per million), price, quantity and on-time delivery, innovation capability, and increasingly the supplier's values.\nSupplier evaluation within the framework of a utility value analysis is followed by a classification into A, B, and C suppliers. A-suppliers are preferred because, for example, they have provided the highest delivery quality in the past.",
    tr: "Tedarikçi değerlendirmesinin yaygın kriterleri arasında ppm oranı (milyonda bir parça), fiyat, miktar ve teslimat sadakati, inovasyon yeteneği ve giderek artan bir şekilde tedarikçinin değer odaklılığı yer almaktadır.\nFayda analizi çerçevesindeki tedarikçi değerlendirmesini, A, B ve C tedarikçileri şeklinde bir sınıflandırma takip eder. A tedarikçileri, örneğin geçmişte en yüksek teslimat kalitesini sağladıkları için tercih edilirler.",
  },
  T11: {
    de: "Marketing bezeichnet Unternehmensaktivitäten, die auf aktuelle und zukünftige Absatzmärkte ausgerichtet sind, sowie die marktorientierte Unternehmensführung insgesamt. Marketing ist damit eine zentrale betriebliche Funktion in einem marktabhängigen Unternehmen.\nIm Marketing-Mix werden die langfristig geplanten Vorgaben in Bezug auf Konzeption, Preispolitik, Kommunikation und Vertrieb in konkrete Maßnahmen umgesetzt.",
    en: "Marketing refers to business activities aimed at current and future sales markets, as well as market-oriented corporate management in general. Marketing is thus a central business function in a market-dependent company.\nIn the marketing mix, the long-term planned specifications regarding conception, pricing policy, communication, and distribution are translated into concrete measures.",
    tr: "Pazarlama, mevcut ve gelecekteki satış pazarlarına yönelik kurumsal faaliyetleri ve bir bütün olarak piyasa odaklı kurumsal yönetimi ifade eder. Bu bağlamda pazarlama, piyasaya bağımlı bir işletmede merkezi bir operasyonel işlevdir.\nPazarlama karmasında, konsept, fiyat politikası, iletişim ve dağıtım ile ilgili uzun vadeli planlanan hedefler somut önlemlere dönüştürülür.",
  },
  T12: {
    de: "Kommunikationsprozesse in Unternehmen finden zwischen Unternehmensleitung und Mitarbeitenden, zwischen den Mitarbeitenden des Unternehmens sowie zwischen Unternehmensleitung bzw. Mitarbeitenden und Geschäftspartnern bzw. Kunden statt. Interne Kommunikation funktioniert, wenn jede Mitarbeiterin und jeder Mitarbeiter weiß und versteht, was zu tun ist, den Hintergrund der eigenen Tätigkeit sowie die konkreten Gesamtziele des Unternehmens kennt und außerdem über die erforderlichen Informationen und Ressourcen verfügt, um die eigene Aufgabe erfolgreich auszuführen.\nErfolgreiche Kommunikation ist eine wesentliche Voraussetzung für ein gutes Arbeitsklima. Sie stärkt das Engagement der Mitarbeitenden, das Unternehmen genießt dauerhaft einen guten Ruf, und Kundenerwartungen werden besser erfüllt.",
    en: "Communication processes in companies take place between management and employees, among the employees of the company, and between management or employees and business partners or customers. Internal communication functions effectively when every employee knows and understands what needs to be done, is aware of the background of their own activities and the company's specific overall goals, and also has the necessary information and resources to successfully perform their tasks.\nSuccessful communication is an essential prerequisite for a good working atmosphere. It strengthens employee engagement, the company continuously enjoys a good reputation, and customer expectations are better met.",
    tr: "Şirketlerde iletişim süreçleri; şirket yönetimi ile çalışanlar arasında, şirket çalışanlarının kendi aralarında ve şirket yönetimi veya çalışanlar ile iş ortakları ya da müşteriler arasında gerçekleşir. İç iletişim; her çalışanın ne yapması gerektiğini bilip anladığı, kendi faaliyetinin arka planını ve şirketin somut genel hedeflerini bildiği, ayrıca görevini başarıyla yerine getirebilmek için gerekli bilgi ve kaynaklara sahip olduğu durumlarda işler.\nBaşarılı bir iletişim, iyi bir çalışma ortamı için temel bir ön koşuldur. Çalışanların bağlılığını güçlendirir, şirket kalıcı olarak iyi bir itibar kazanır ve müşteri beklentileri daha iyi karşılanır.",
  },
  T13: {
    de: "Das IKT-Management ist für den gesamten digitalen Informations- und Kommunikationsbereich eines modernen Unternehmens verantwortlich; häufig wird es auch als IT-Management (Information Technology Management) bezeichnet.\nEs ist zuständig für Planung, Beschaffung und Einsatz der IKT-Infrastruktur, also der informationstechnischen und personellen Ressourcen. Darüber hinaus trägt es Verantwortung für den Betrieb der operativen Geschäfts- und Anwendungssysteme sowie für das gesamte Informations- und Kommunikationssystem des Unternehmens.\nEine besondere rechtliche und ethische Herausforderung wird zunehmend der Umgang mit KI.",
    en: "ICT management is responsible for the entire digital information and communication area of a modern company; it is often also referred to as IT management (Information Technology Management).\nIt is responsible for planning, procuring, and deploying the ICT infrastructure, i.e., the information technology and personnel resources. Furthermore, it is responsible for the operation of the operational business and application systems, as well as for the company's entire information and communication system.\nThe handling of AI is increasingly becoming a particular legal and ethical challenge.",
    tr: "BİT yönetimi, modern bir işletmenin tüm dijital bilgi ve iletişim alanından sorumludur; genellikle BT yönetimi (Bilgi Teknolojileri Yönetimi) olarak da adlandırılır.\nBİT altyapısının, yani bilgi teknolojisi ve insan kaynaklarının planlanması, tedariki ve kullanımından sorumludur. Ayrıca, operasyonel iş ve uygulama sistemlerinin işletilmesinin yanı sıra şirketin tüm bilgi ve iletişim sisteminden de sorumluluk taşır.\nYapay zeka kullanımı, giderek artan bir şekilde özel bir hukuki ve etik zorluk haline gelmektedir.",
  },
  T14: {
    de: "Controlling ist ein Steuerungs- und Koordinationskonzept zur Unterstützung der Unternehmensleitung und der Führungskräfte bei der ergebnisorientierten Planung sowie bei der Umsetzung und Kontrolle unternehmerischer Aktivitäten.\nGrundsätzlich wird zwischen langfristigem strategischem Controlling („Tun wir die richtigen Dinge?“) und kurz- bis mittelfristigem operativem Controlling („Tun wir die Dinge richtig?“) unterschieden.",
    en: "Controlling is a management and coordination concept that supports company management and executives in results-oriented planning, as well as in the implementation and control of business activities.\nA basic distinction is made between long-term strategic controlling (\"Are we doing the right things?\") and short- to medium-term operational controlling (\"Are we doing things right?\").",
    tr: "Controlling, şirket yönetimi ve yöneticileri sonuç odaklı planlama ile kurumsal faaliyetlerin uygulanması ve denetlenmesi süreçlerinde destekleyen bir yönetim ve koordinasyon konseptidir.\nTemel olarak, uzun vadeli stratejik controlling (\"Doğru işleri mi yapıyoruz?\") ile kısa ve orta vadeli operasyonel controlling (\"İşleri doğru yapıyor muyuz?\") arasında bir ayrım yapılır.",
  },
  T15: {
    de: "Mithilfe von Benchmarking kann ein Unternehmen Best Practices identifizieren und auf das eigene Unternehmen übertragen, um sich weiterzuentwickeln. Ziel des Benchmarkings ist es, die „richtigen Dinge“ zu tun (Effektivität) und „die Dinge richtig“ zu tun (Effizienz). Benchmarking kann auch zwischen vergleichbaren Unternehmensteilen durchgeführt werden, beispielsweise zwischen verschiedenen Produktionsstandorten oder Vertriebsbereichen.\nBenchmarking kann zeitaufwendig sein und sollte daher vor allem für langfristige Planungen eingesetzt und auf Bereiche mit besonders hohem Verbesserungspotenzial fokussiert werden.\nDerzeit gibt es keine international standardisierten Benchmarks.",
    en: "By using benchmarking, a company can identify best practices and transfer them to its own operations in order to develop further. The goal of benchmarking is to do the \"right things\" (effectiveness) and to \"do things right\" (efficiency). Benchmarking can also be carried out between comparable parts of a company, for example, between different production sites or sales departments.\nBenchmarking can be time-consuming and should therefore primarily be used for long-term planning and focused on areas with particularly high potential for improvement.\nCurrently, there are no internationally standardized benchmarks.",
    tr: "Benchmarking sayesinde bir şirket, en iyi uygulamaları (best practices) belirleyebilir ve gelişmek adına bunları kendi bünyesine uyarlayabilir. Benchmarking'in amacı, \"doğru şeyleri\" yapmak (etkililik) ve \"şeyleri doğru\" yapmaktır (verimlilik). Benchmarking, farklı üretim tesisleri veya satış bölgeleri gibi benzer şirket birimleri arasında da gerçekleştirilebilir.\nBenchmarking zaman alıcı olabilir; bu nedenle öncelikle uzun vadeli planlamalar için kullanılmalı ve iyileştirme potansiyeli özellikle yüksek olan alanlara odaklanılmalıdır.\nŞu an için uluslararası düzeyde standartlaştırılmış bir benchmark bulunmamaktadır.",
  },
  T16: {
    de: "Die SWOT-Analyse dient der Vorbereitung der strategischen Unternehmensplanung. SWOT steht für „Strengths“, „Weaknesses“, „Opportunities“ und „Threats“. Die SWOT-Analyse betrachtet somit sowohl interne Faktoren (Stärken und Schwächen) als auch externe Faktoren (Chancen und Risiken).\nEine regelmäßige SWOT-Analyse ist ein geeignetes Instrument, um Banken und Stakeholdern eine rationale Einschätzung zu ermöglichen. Vor Anwendung der SWOT-Analyse und der jeweiligen Methode müssen die strategischen Ziele des Unternehmens definiert werden, beispielsweise mithilfe sogenannter Balanced Scorecards, um klare Bezugsgrößen zu schaffen.",
    en: "The SWOT analysis serves to prepare strategic business planning. SWOT stands for \"Strengths\", \"Weaknesses\", \"Opportunities\", and \"Threats\". The SWOT analysis thus considers both internal factors (strengths and weaknesses) and external factors (opportunities and threats).\nA regular SWOT analysis is a suitable tool to enable banks and stakeholders to make a rational assessment. Before applying the SWOT analysis and its respective method, the company's strategic goals must be defined, for example with the help of so-called Balanced Scorecards, to create clear reference points.",
    tr: "SWOT analizi, stratejik kurumsal planlamanın hazırlanmasına hizmet eder. SWOT; \"Strengths\" (Güçlü Yönler), \"Weaknesses\" (Zayıf Yönler), \"Opportunities\" (Fırsatlar) ve \"Threats\" (Tehditler) kelimelerinin baş harflerinden oluşur. Dolayısıyla SWOT analizi, hem iç faktörleri (güçlü ve zayıf yönler) hem de dış faktörleri (fırsatlar ve riskler) ele alır.\nDüzenli bir SWOT analizi, bankalara ve paydaşlara rasyonel bir değerlendirme imkanı sunmak için uygun bir araçtır. SWOT analizini ve ilgili yöntemi uygulamadan önce, net referans noktaları oluşturmak amacıyla, örneğin Balanced Scorecard (Dengeli Puan Kartı) gibi yöntemler kullanılarak şirketin stratejik hedeflerinin tanımlanması gerekir.",
  },
  T17: {
    de: "Mediation (lateinisch: Vermittlung) ist ein strukturiertes Verfahren, das die konstruktive Lösung oder Vermeidung von Konflikten ermöglichen soll.\nDie Konfliktparteien möchten mit Unterstützung einer dritten, unparteiischen und neutralen Person, nämlich der Mediatorin bzw. des Mediators, eine einvernehmliche Vereinbarung erreichen, die ihren Bedürfnissen und Interessen entspricht.\nDer deutsche Schriftsteller Kurt Tucholsky (1890–1935) bringt in einem Zitat klar zum Ausdruck, worauf es bei Mediation ankommt:\nWer streitet, sollte wissen, dass nie einer ganz recht hat und der andere ganz unrecht.",
    en: "Mediation (Latin: intermediation) is a structured process designed to enable the constructive resolution or avoidance of conflicts.\nThe conflicting parties, with the support of a third, impartial, and neutral person—the mediator—aim to reach a consensual agreement that meets their needs and interests.\nThe German writer Kurt Tucholsky (1890–1935) clearly expresses what mediation is all about in a quote:\nHe who disputes should know that no one is ever entirely right and the other entirely wrong.",
    tr: "Arabuluculuk (Latince: aracılık), çatışmaların yapıcı bir şekilde çözülmesini veya önlenmesini sağlamayı amaçlayan yapılandırılmış bir süreçtir.\nÇatışan taraflar, tarafsız ve bağımsız bir üçüncü kişi olan arabulucunun desteğiyle, ihtiyaç ve çıkarlarına uygun, karşılıklı mutabakata dayalı bir anlaşmaya varmayı hedeflerler.\nAlman yazar Kurt Tucholsky (1890–1935), bir sözünde arabuluculuğun ne anlama geldiğini açıkça ifade eder:\nTartışan herkes, hiçbir zaman bir tarafın tamamen haklı, diğerinin ise tamamen haksız olmadığını bilmelidir.",
  },
  T18: {
    de: "Ein Audit ist ein Untersuchungs- und Prüfverfahren, das Prozesse, Produkte oder Dienstleistungen im Hinblick auf die Erfüllung von Anforderungen und Richtlinien bewertet.\nDer anschließende Auditbericht bildet die Grundlage für die Umsetzung von Verbesserungsvorschlägen.\nEin Audit hat positive Wirkung, wenn es konstruktiv durchgeführt wird und Verbesserungspotenziale aufzeigt. Audits werden häufig eingesetzt, um die Wirksamkeit von Maßnahmen im Rahmen von Qualitätsmanagementsystemen zu überprüfen. Sie werden von speziell geschulten internen oder externen Auditorinnen und Auditoren durchgeführt.",
    en: "An audit is an investigation and inspection procedure that evaluates processes, products, or services with regard to their compliance with requirements and guidelines.\nThe subsequent audit report forms the basis for implementing suggestions for improvement.\nAn audit has a positive effect when it is conducted constructively and identifies potential for improvement. Audits are frequently used to verify the effectiveness of measures within the framework of quality management systems. They are carried out by specially trained internal or external auditors.",
    tr: "Denetim, süreçleri, ürünleri veya hizmetleri gerekliliklerin ve yönergelerin karşılanması açısından değerlendiren bir inceleme ve kontrol prosedürüdür.\nBunu takip eden denetim raporu, iyileştirme önerilerinin uygulanması için temel oluşturur.\nBir denetim, yapıcı bir şekilde gerçekleştirildiğinde ve iyileştirme potansiyellerini ortaya koyduğunda olumlu bir etkiye sahiptir. Denetimler, kalite yönetim sistemleri kapsamındaki önlemlerin etkinliğini kontrol etmek için sıklıkla kullanılır. Bu denetimler, özel eğitim almış iç veya dış denetçiler tarafından gerçekleştirilir.",
  },
  T19: {
    de: "Ein Unternehmensrating dient der Beurteilung der Zukunftsfähigkeit eines Unternehmens und trifft auf Grundlage eines nachvollziehbar ermittelten Ratings eine Aussage über die Bonität und Zuverlässigkeit des Unternehmens als Geschäftspartner innerhalb der Wertschöpfungskette.\nDas Unternehmensrating umfasst die Vergabe einer Bewertung anhand quantitativer und qualitativer Kriterien sowie zusätzlich die Erstellung eines Ratingberichts. Zu den quantitativen Kriterien gehören beispielsweise Kennzahlen zur Vermögens-, Ertrags- und Finanzlage, die für das jeweilige Unternehmen auf Grundlage von drei Jahresabschlüssen ermittelt und hinsichtlich ihrer Qualität beurteilt werden.",
    en: "A corporate rating assesses a company's future viability and, based on a transparently determined rating, makes a statement about the company's creditworthiness and reliability as a business partner within the value chain.\nThe corporate rating includes the assignment of an evaluation based on quantitative and qualitative criteria, as well as the preparation of a rating report. Quantitative criteria include, for example, key figures on asset, earnings, and financial positions, which are determined for the respective company based on three annual financial statements and assessed for their quality.",
    tr: "Bir şirket derecelendirmesi, bir şirketin gelecekteki sürdürülebilirliğini değerlendirmeye yarar ve anlaşılır bir şekilde belirlenmiş bir derecelendirmeye dayanarak, değer zinciri içindeki bir iş ortağı olarak şirketin kredibilitesi ve güvenilirliği hakkında bir beyanda bulunur.\nŞirket derecelendirmesi, nicel ve nitel kriterlere dayalı bir değerlendirmenin yapılmasını ve buna ek olarak bir derecelendirme raporunun hazırlanmasını kapsar. Nicel kriterler arasında, örneğin ilgili şirket için üç yıllık mali tablolar temelinde belirlenen ve kaliteleri açısından değerlendirilen varlık, gelir ve finansal durum göstergeleri yer alır.",
  },
  T20: {
    de: "Zertifizierungen sind Verfahren, mit denen die Einhaltung bestimmter Normen, Standards und Richtlinien für Produkte und Dienstleistungen sowie deren jeweilige Herstellungsprozesse einschließlich Geschäftsbeziehungen nachgewiesen werden kann.\nEin gutes Zertifikat ist etwas, woran sich ein Unternehmen messen lassen kann. Wer damit wirbt, wird von der Öffentlichkeit genau betrachtet. Deshalb lohnen sich langfristig nur ehrliche Zertifikate. Wenn sie jedoch wirklich mit Überzeugung und Konsequenz gelebt werden, können sie einem Unternehmen dauerhaft ein hohes Ansehen verschaffen",
    en: "Certifications are procedures that can be used to demonstrate compliance with specific norms, standards, and guidelines for products and services, as well as their respective manufacturing processes, including business relationships.\nA good certificate is something by which a company can be measured. Whoever advertises with one will be scrutinized by the public. Therefore, in the long run, only honest certificates are worthwhile. However, if they are truly lived with conviction and consistency, they can permanently earn a company a high reputation.",
    tr: "Sertifikalar, ürün ve hizmetlerin yanı sıra iş ilişkileri de dahil olmak üzere bunların üretim süreçleri için belirli normlara, standartlara ve yönergelere uyumun kanıtlanabildiği prosedürlerdir.\nİyi bir sertifika, bir şirketin kendisini ölçebileceği bir değerdir. Bununla reklam yapanlar, kamuoyu tarafından yakından incelenir. Bu nedenle uzun vadede sadece dürüst sertifikalar değerlidir. Ancak gerçekten inançla ve tutarlılıkla uygulandıklarında, bir şirkete kalıcı olarak yüksek bir itibar kazandırabilirler.",
  },
};
